--[[
	Lunar UI for Frekks Hail v3
	Linoria/Obsidian-compatible facade rendered with the Lunar design: plum glass
	window, UIBlur backdrop, UIShadow glows, pixel-art flowers and the Frekks Hail
	wordmark as the window title.

	It replaces the previous `linoria_library` module and keeps its public surface:
	Library.Toggles / Library.Options, Window:AddTab, Tab:AddLeftGroupbox,
	Tab:AddSubTab, groupbox:AddToggle(id, info) ... Toggle:AddKeyPicker, etc.
]]

local cloneref = cloneref or function(o)
	return o
end

local function service(name)
	LPH_ATTRIBUTES(VM(NONE));
	return cloneref(game:GetService(name))
end

local function elevate()
	LPH_ATTRIBUTES(VM(NONE));
	local fn = __FrekksHailElevateIdentity
	if type(fn) == "function" then
		return pcall(fn)
	elseif type(setthreadidentity) == "function" then
		return pcall(setthreadidentity, 8)
	end
	return false
end

-- Executors can drop the thread identity between yields; retry once after
-- raising it, like the previous library's uiOperation did.
local function guarded(fn, ...)
	LPH_ATTRIBUTES(VM(NONE));
	local ok, result = pcall(fn, ...)
	if not ok and string.find(tostring(result), "lacking capability", 1, true) then
		elevate()
		ok, result = pcall(fn, ...)
	end
	if not ok then
		error(result, 0)
	end
	return result
end

local function makeInstance(class)
	LPH_ATTRIBUTES(VM(NONE));
	return guarded(Instance.new, class)
end

