---------------------------------------------------------------------
-- Helpers
---------------------------------------------------------------------

local function track(conn)
	LPH_ATTRIBUTES(VM(NONE));
	table.insert(Library._connections, conn)
	return conn
end

local function connect(signal, fn)
	LPH_ATTRIBUTES(VM(NONE));
	return track(signal:Connect(fn))
end

local function tween(instance, time, props, style, direction)
	LPH_ATTRIBUTES(VM(NONE));
	local t = TweenService:Create(instance, TweenInfo.new(time, style or EASE, direction or OUT), props)
	t:Play()
	return t
end

local function trySet(instance, prop, value)
	LPH_ATTRIBUTES(VM(NONE));
	return pcall(function()
		LPH_ATTRIBUTES(VM(NONE));
		instance[prop] = value
	end)
end

local function newRaw(class, props, children)
	LPH_ATTRIBUTES(VM(NONE));
	local inst = Instance.new(class)
	if inst:IsA("GuiObject") then
		inst.BorderSizePixel = 0
		if class ~= "Frame" and class ~= "ScrollingFrame" then
			inst.BackgroundTransparency = 1
		end
		if class == "TextButton" or class == "ImageButton" then
			inst.AutoButtonColor = false
		end
		if class == "TextButton" then
			inst.Text = ""
		end
	end
	local parent
	if props then
		for key, value in pairs(props) do
			if key == "Parent" then
				parent = value
			elseif key == "Theme" then
				paint(inst, value)
			else
				inst[key] = value
			end
		end
	end
	if children then
		for _, child in ipairs(children) do
			child.Parent = inst
		end
	end
	if parent then
		inst.Parent = parent
	end
	return inst
end

local function new(class, props, children)
	LPH_ATTRIBUTES(VM(NONE));
	return guarded(newRaw, class, props, children)
end

local function px(n)
	LPH_ATTRIBUTES(VM(NONE));
	return UDim.new(0, n)
end

local function corner(parent, radius)
	LPH_ATTRIBUTES(VM(NONE));
	return new("UICorner", { CornerRadius = px(radius), Parent = parent })
end

local CORNERS_OK = pcall(function()
	LPH_ATTRIBUTES(VM(NONE));
	local c = makeInstance("UICorner")
	c.TopLeftRadius = px(1)
	c:Destroy()
end)

local function corners(parent, topLeft, topRight, bottomRight, bottomLeft)
	LPH_ATTRIBUTES(VM(NONE));
	local c = makeInstance("UICorner")
	if CORNERS_OK then
		c.TopLeftRadius = px(topLeft)
		c.TopRightRadius = px(topRight)
		c.BottomRightRadius = px(bottomRight)
		c.BottomLeftRadius = px(bottomLeft)
	else
		c.CornerRadius = px(0)
	end
	c.Parent = parent
	return c
end

local function stroke(parent, key, thickness, transparency)
	LPH_ATTRIBUTES(VM(NONE));
	local s = makeInstance("UIStroke")
	s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
	s.Thickness = thickness or 1
	s.Transparency = transparency or 0
	if key then
		paint(s, { Color = key })
	end
	s.Parent = parent
	return s
end

local function colorSeq(...)
	LPH_ATTRIBUTES(VM(NONE));
	local points = { ... }
	if #points == 2 and typeof(points[1]) == "Color3" then
		return ColorSequence.new(points[1], points[2])
	end
	local keys = {}
	for i = 1, #points, 2 do
		table.insert(keys, ColorSequenceKeypoint.new(points[i], points[i + 1]))
	end
	return ColorSequence.new(keys)
end

local function numberSeq(...)
	LPH_ATTRIBUTES(VM(NONE));
	local points = { ... }
	local keys = {}
	for i = 1, #points, 2 do
		table.insert(keys, NumberSequenceKeypoint.new(points[i], points[i + 1]))
	end
	return NumberSequence.new(keys)
end

-- gradient(parent, rotation, keys, transparency): keys is a list of {time, "ThemeKey"} or two theme keys
local function gradient(parent, rotation, keys, transparency)
	LPH_ATTRIBUTES(VM(NONE));
	local g = makeInstance("UIGradient")
	g.Rotation = rotation or 0
	if keys then
		local function build(target)
			LPH_ATTRIBUTES(VM(NONE));
			if #keys == 2 and type(keys[1]) == "string" then
				target.Color = ColorSequence.new(Theme[keys[1]], Theme[keys[2]])
			else
				local points = {}
				for _, k in ipairs(keys) do
					table.insert(points, ColorSequenceKeypoint.new(k[1], Theme[k[2]]))
				end
				target.Color = ColorSequence.new(points)
			end
		end
		build(g)
		paintedGradients[g] = build
	end
	if transparency then
		g.Transparency = transparency
	end
	g.Parent = parent
	return g
end

local function isPress(input)
	LPH_ATTRIBUTES(VM(NONE));
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

local function isMove(input)
	LPH_ATTRIBUTES(VM(NONE));
	return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
end

local function round(n)
	LPH_ATTRIBUTES(VM(NONE));
	return math.floor(n + 0.5)
end

local function cloneTable(source)
	LPH_ATTRIBUTES(VM(NONE));
	local out = {}
	for k, v in pairs(source) do
		out[k] = v
	end
	return out
end

local function mouseLocation()
	LPH_ATTRIBUTES(VM(NONE));
	local insetX, insetY = 0, 0
	local ok, inset = pcall(GuiService.GetGuiInset, GuiService)
	if ok and typeof(inset) == "Vector2" then
		insetX, insetY = inset.X, inset.Y
	end
	local pos = UserInputService:GetMouseLocation()
	return Vector2.new(pos.X - insetX, pos.Y - insetY)
end

-- Runs a user callback through Library:SafeCallback (the script installs an
-- error-reporting version) on its own thread, like the previous library did.
local function fire(fn, ...)
	LPH_ATTRIBUTES(VM(NONE));
	if type(fn) ~= "function" then
		return
	end
	local args = table.pack(...)
	task.spawn(function()
		LPH_ATTRIBUTES(VM(NONE));
		elevate()
		local safe = Library.SafeCallback
		if type(safe) == "function" then
			safe(Library, fn, table.unpack(args, 1, args.n))
		else
			local ok, err = pcall(fn, table.unpack(args, 1, args.n))
			if not ok then
				warn("[Lunar] callback error: " .. tostring(err))
			end
		end
	end)
end

