-- Keys
---------------------------------------------------------------------

local KEY_NONE = Enum.KeyCode.Unknown

local function enumToString(value)
	LPH_ATTRIBUTES(VM(NONE));
	if typeof(value) ~= "EnumItem" then
		return tostring(value)
	end
	if value == KEY_NONE then
		return "None"
	end
	if value.EnumType == Enum.UserInputType then
		if value == Enum.UserInputType.MouseButton1 then
			return "MB1"
		elseif value == Enum.UserInputType.MouseButton2 then
			return "MB2"
		elseif value == Enum.UserInputType.MouseButton3 then
			return "MB3"
		end
	end
	return value.Name
end

local KEY_ALIASES = {
	MB1 = Enum.UserInputType.MouseButton1,
	MB2 = Enum.UserInputType.MouseButton2,
	MB3 = Enum.UserInputType.MouseButton3,
	MouseButton1 = Enum.UserInputType.MouseButton1,
	MouseButton2 = Enum.UserInputType.MouseButton2,
	MouseButton3 = Enum.UserInputType.MouseButton3,
	None = KEY_NONE,
	Unknown = KEY_NONE,
}

local function stringToEnum(value)
	LPH_ATTRIBUTES(VM(NONE));
	if typeof(value) == "EnumItem" then
		return value
	end
	local text = tostring(value or "")
	if KEY_ALIASES[text] then
		return KEY_ALIASES[text]
	end
	local ok, item = pcall(function()
		LPH_ATTRIBUTES(VM(NONE));
		return Enum.KeyCode[text]
	end)
	if ok and item then
		return item
	end
	ok, item = pcall(function()
		LPH_ATTRIBUTES(VM(NONE));
		return Enum.UserInputType[text]
	end)
	if ok and item then
		return item
	end
	return KEY_NONE
end

local KEY_LABELS = {
	MB1 = "Left Mouse", MB2 = "Right Mouse", MB3 = "Middle Mouse",
	LeftShift = "Left Shift", RightShift = "Right Shift", LeftControl = "Left Ctrl", RightControl = "Right Ctrl",
	LeftAlt = "Left Alt", RightAlt = "Right Alt", CapsLock = "Caps Lock", Return = "Enter",
}

local function keyLabel(value)
	LPH_ATTRIBUTES(VM(NONE));
	local name = enumToString(value)
	return KEY_LABELS[name] or (string.gsub(name, "(%l)(%u)", "%1 %2"))
end

local function inputMatches(input, value)
	LPH_ATTRIBUTES(VM(NONE));
	if typeof(value) ~= "EnumItem" or value == KEY_NONE then
		return false
	end
	if value.EnumType == Enum.KeyCode then
		return input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == value
	end
	return input.UserInputType == value
end

---------------------------------------------------------------------
-- Assets: decode the embedded PNGs into the workspace once, then load
-- them through getcustomasset.
---------------------------------------------------------------------

local Assets = {}
local ICONS = EMBEDDED.icons or {}
local ICON_CELL = EMBEDDED.iconCell or 48

local function base64Decode(data)
	LPH_ATTRIBUTES(VM(NONE));
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local lut = table.create(256, 0)
	for i = 1, 64 do
		lut[string.byte(alphabet, i) + 1] = i - 1
	end
	local len = #data
	local pad = 0
	if string.sub(data, -2) == "==" then
		pad = 2
	elseif string.sub(data, -1) == "=" then
		pad = 1
	end
	local outLen = math.floor(len / 4) * 3 - pad
	if buffer then
		local src = buffer.fromstring(data)
		local out = buffer.create(outLen)
		local o = 0
		for i = 0, len - 4, 4 do
			local n = lut[buffer.readu8(src, i) + 1] * 262144
				+ lut[buffer.readu8(src, i + 1) + 1] * 4096
				+ lut[buffer.readu8(src, i + 2) + 1] * 64
				+ lut[buffer.readu8(src, i + 3) + 1]
			if o < outLen then
				buffer.writeu8(out, o, bit32.band(bit32.rshift(n, 16), 255))
			end
			if o + 1 < outLen then
				buffer.writeu8(out, o + 1, bit32.band(bit32.rshift(n, 8), 255))
			end
			if o + 2 < outLen then
				buffer.writeu8(out, o + 2, bit32.band(n, 255))
			end
			o += 3
		end
		return buffer.tostring(out)
	end
	local parts, chunk, o = {}, {}, 0
	for i = 1, len - 3, 4 do
		local a, b, c, d = string.byte(data, i, i + 3)
		local n = lut[a + 1] * 262144 + lut[b + 1] * 4096 + lut[c + 1] * 64 + lut[d + 1]
		for shift = 16, 0, -8 do
			if o < outLen then
				chunk[#chunk + 1] = string.char(bit32.band(bit32.rshift(n, shift), 255))
				o += 1
			end
		end
		if #chunk >= 3000 then
			parts[#parts + 1] = table.concat(chunk)
			chunk = {}
		end
	end
	parts[#parts + 1] = table.concat(chunk)
	return table.concat(parts)
end

local function ensureFolder(path)
	LPH_ATTRIBUTES(VM(NONE));
	if type(makefolder) ~= "function" then
		return false
	end
	local current = ""
	for part in string.gmatch(path, "[^/]+") do
		current = current == "" and part or (current .. "/" .. part)
		local exists = type(isfolder) == "function" and isfolder(current)
		if not exists then
			pcall(makefolder, current)
		end
	end
	return true
end

local ASSET_NAMES = { "background", "blossoms", "flowers_left", "flowers_right", "petal", "glow", "icons", "logo" }

local function loadAssets(folder)
	LPH_ATTRIBUTES(VM(NONE));
	local getasset = getcustomasset or getsynasset
	local canWrite = type(writefile) == "function" and type(getasset) == "function"
	local files = EMBEDDED.files or {}
	local dir = folder .. "/assets/lunar-" .. tostring(EMBEDDED.version or "dev")
	if canWrite then
		ensureFolder(dir)
	end
	for _, name in ipairs(ASSET_NAMES) do
		local id
		if canWrite and files[name] then
			local ok, result = pcall(function()
				LPH_ATTRIBUTES(VM(NONE));
				local path = dir .. "/" .. name .. ".png"
				local exists = type(isfile) == "function" and isfile(path)
				if not exists then
					writefile(path, base64Decode(files[name]))
				end
				return getasset(path)
			end)
			if ok and type(result) == "string" then
				id = result
			end
		end
		Assets[name] = id or ""
	end
end

-- Icon names used by the script and the previous library, mapped onto the sheet.
local ICON_ALIASES = {
	combat = "swords", triggerbot = "mouse-pointer-click", trigger = "mouse-pointer-click",
	visuals = "eye", movement = "zap", player = "user", silent = "ghost", rage = "flame",
	sliders = "sliders-horizontal", grid = "layout-grid", settings = "settings", misc = "layout-grid",
	esp = "eye", world = "globe", character = "user", spoofer = "venetian-mask",
}

local function setIcon(image, name)
	LPH_ATTRIBUTES(VM(NONE));
	if type(name) ~= "string" or name == "" then
		image.Image = ""
		return false
	end
	if string.find(name, "^rbx") or string.find(name, "^http") then
		image.Image = name
		image.ImageRectOffset = Vector2.new(0, 0)
		image.ImageRectSize = Vector2.new(0, 0)
		return true
	end
	local cell = ICONS[name] or ICONS[ICON_ALIASES[string.lower(name)] or ""]
	if cell and Assets.icons ~= "" then
		image.Image = Assets.icons
		image.ImageRectOffset = Vector2.new(cell[1], cell[2])
		image.ImageRectSize = Vector2.new(ICON_CELL, ICON_CELL)
		return true
	end
	image.Image = ""
	return false
end

local function icon(name, size, colorKey, props)
	LPH_ATTRIBUTES(VM(NONE));
	local image = new("ImageLabel", {
		Name = "Icon",
		Size = UDim2.fromOffset(size, size),
		ScaleType = Enum.ScaleType.Fit,
	})
	if colorKey then
		paint(image, { ImageColor3 = colorKey })
	end
	setIcon(image, name)
	if props then
		for key, value in pairs(props) do
			image[key] = value
		end
	end
	return image
end

