local function iconForTitle(title, fallback)
	LPH_ATTRIBUTES(VM(NONE));
	local lower = string.lower(tostring(title or ""))
	for _, pair in ipairs(TITLE_ICONS) do
		if string.find(lower, pair[1], 1, true) then
			return pair[2]
		end
	end
	return fallback or "box"
end

---------------------------------------------------------------------
-- Glow: UIShadow where the client has it, 9-slice halo otherwise.
-- Every glow scales with Library.GlowStrength (the "Glow strength" slider).
---------------------------------------------------------------------

local SHADOW_OK = pcall(function()
	LPH_ATTRIBUTES(VM(NONE));
	makeInstance("UIShadow"):Destroy()
end)

local glows = setmetatable({}, { __mode = "k" })

local function glowFactor()
	LPH_ATTRIBUTES(VM(NONE));
	return math.clamp((tonumber(Library.GlowStrength) or 0.2) / 0.2, 0, 2.5)
end

local function effective(base, colorIsBlack)
	LPH_ATTRIBUTES(VM(NONE));
	if colorIsBlack then
		return base -- drop shadows keep their depth
	end
	return math.clamp(1 - (1 - base) * glowFactor(), 0, 1)
end

local function glow(parent, opts)
	LPH_ATTRIBUTES(VM(NONE));
	local handle = { Base = opts.Transparency or 0.5, Black = opts.Color == "Black" }
	if SHADOW_OK then
		local shadow = makeInstance("UIShadow")
		shadow.Name = "Glow"
		if handle.Black then
			shadow.Color = BLACK
		else
			paint(shadow, { Color = opts.Color or "Glow" })
		end
		shadow.BlurRadius = px(opts.Blur or 12)
		local offset = opts.Offset or Vector2.new(0, 0)
		trySet(shadow, "Spread", UDim2.fromOffset(opts.Spread or 0, opts.Spread or 0))
		trySet(shadow, "Offset", UDim2.fromOffset(offset.X, offset.Y))
		trySet(shadow, "ShowBehindParent", false)
		pcall(function()
			LPH_ATTRIBUTES(VM(NONE));
			shadow.Mode = Enum.ApplyShadowMode.Shape
		end)
		shadow.Transparency = effective(handle.Base, handle.Black)
		shadow.Parent = parent
		handle.Instance, handle.Property = shadow, "Transparency"
	elseif Assets.glow ~= "" then
		local scale = math.max(0.2, (opts.Blur or 12) / 20)
		local margin = 32 * scale + (opts.Spread or 0)
		local offset = opts.Offset or Vector2.new(0, 0)
		local halo = new("ImageLabel", {
			Name = "Glow",
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, offset.X, 0.5, offset.Y),
			Size = UDim2.new(1, margin * 2, 1, margin * 2),
			Image = Assets.glow,
			ImageTransparency = effective(handle.Base, handle.Black),
			ScaleType = Enum.ScaleType.Slice,
			SliceCenter = Rect.new(47, 47, 49, 49),
			SliceScale = scale,
			ZIndex = 0,
			Parent = parent,
		})
		if handle.Black then
			halo.ImageColor3 = BLACK
		else
			paint(halo, { ImageColor3 = opts.Color or "Glow" })
		end
		handle.Instance, handle.Property = halo, "ImageTransparency"
	end
	if handle.Instance then
		glows[handle] = true
	end
	return handle
end

local function setGlow(handle, base, time)
	LPH_ATTRIBUTES(VM(NONE));
	if not handle then
		return
	end
	handle.Base = base
	if not handle.Instance then
		return
	end
	local value = effective(base, handle.Black)
	if time and time > 0 then
		tween(handle.Instance, time, { [handle.Property] = value })
	else
		handle.Instance[handle.Property] = value
	end
end

local function refreshGlows()
	LPH_ATTRIBUTES(VM(NONE));
	for handle in pairs(glows) do
		if handle.Instance and handle.Instance.Parent then
			handle.Instance[handle.Property] = effective(handle.Base, handle.Black)
		end
	end
end

---------------------------------------------------------------------
-- Fade: tween the visible part of a subtree to transparent and back.
-- Hidden subtrees (inactive pages) are skipped to keep the tween count low.
---------------------------------------------------------------------

local FADE_PROPS = {
	Frame = { "BackgroundTransparency" },
	ScrollingFrame = { "BackgroundTransparency", "ScrollBarImageTransparency" },
	TextLabel = { "BackgroundTransparency", "TextTransparency" },
	TextButton = { "BackgroundTransparency", "TextTransparency" },
	TextBox = { "BackgroundTransparency", "TextTransparency" },
	ImageLabel = { "BackgroundTransparency", "ImageTransparency" },
	ImageButton = { "BackgroundTransparency", "ImageTransparency" },
	ViewportFrame = { "BackgroundTransparency", "ImageTransparency" },
	UIStroke = { "Transparency" },
	UIShadow = { "Transparency" },
}

local fades = setmetatable({}, { __mode = "k" })

local function fadeFinish(root)
	LPH_ATTRIBUTES(VM(NONE));
	local state = fades[root]
	if not state then
		return
	end
	fades[root] = nil
	for _, t in ipairs(state.tweens) do
		t:Cancel()
	end
	for _, item in ipairs(state.items) do
		pcall(function()
			LPH_ATTRIBUTES(VM(NONE));
			item[1][item[2]] = item[3]
		end)
	end
end

local function fade(root, show, time, onDone)
	LPH_ATTRIBUTES(VM(NONE));
	fadeFinish(root)
	local items = {}
	local function collect(inst)
		LPH_ATTRIBUTES(VM(NONE));
		local props = FADE_PROPS[inst.ClassName]
		if props then
			for _, prop in ipairs(props) do
				local value = inst[prop]
				if value < 1 then
					table.insert(items, { inst, prop, value })
				end
			end
		end
		if inst:IsA("GuiObject") and not inst.Visible and inst ~= root then
			return
		end
		for _, child in ipairs(inst:GetChildren()) do
			collect(child)
		end
	end
	collect(root)

	local state = { items = items, tweens = {} }
	fades[root] = state
	local info = TweenInfo.new(time, Enum.EasingStyle.Quad, OUT)
	if show then
		for _, item in ipairs(items) do
			item[1][item[2]] = 1
		end
		root.Visible = true
	end
	for _, item in ipairs(items) do
		local t = TweenService:Create(item[1], info, { [item[2]] = show and item[3] or 1 })
		table.insert(state.tweens, t)
		t:Play()
	end
	task.delay(time, function()
		LPH_ATTRIBUTES(VM(NONE));
		if fades[root] ~= state then
			return
		end
		if not show then
			root.Visible = false
		end
		fadeFinish(root)
		if onDone then
			onDone()
		end
	end)
end

---------------------------------------------------------------------
-- Backdrop blur: UIBlur when the client has it, otherwise a glass part
-- with a DepthOfFieldEffect placed just in front of the camera.
---------------------------------------------------------------------

local function createGlassBlur(target)
	LPH_ATTRIBUTES(VM(NONE));
	local folder = makeInstance("Folder")
	folder.Name = HttpService:GenerateGUID(false)
	local part = makeInstance("Part")
	part.Name = "Glass"
	part.Material = Enum.Material.Glass
	part.Color = BLACK
	part.Transparency = 0.98
	part.Anchored = true
	part.CanCollide = false
	part.CastShadow = false
	part.Locked = true
	part.Size = Vector3.new(1, 1, 0)
	trySet(part, "CanQuery", false)
	trySet(part, "CanTouch", false)
	local mesh = makeInstance("SpecialMesh")
	mesh.MeshType = Enum.MeshType.Brick
	mesh.Offset = Vector3.new(0, 0, -0.000001)
	mesh.Parent = part
	part.Parent = folder
	local dof = makeInstance("DepthOfFieldEffect")
	dof.Name = folder.Name
	dof.FarIntensity = 0
	dof.FocusDistance = 0.05
	dof.InFocusRadius = 0.1
	dof.NearIntensity = 1

	local enabled = false
	local function update()
		LPH_ATTRIBUTES(VM(NONE));
		local camera = workspace.CurrentCamera
		if not enabled or not camera then
			return
		end
		if folder.Parent ~= camera then
			folder.Parent = camera
		end
		local pos, size = target.AbsolutePosition, target.AbsoluteSize
		local inset = 8 + 48 * math.clamp(camera.ViewportSize.Y / 2560, 0, 1)
		local x0, y0 = pos.X + inset / 2, pos.Y + inset / 2
		local x1, y1 = pos.X + size.X - inset / 2, pos.Y + size.Y - inset / 2
		if x1 <= x0 or y1 <= y0 then
			return
		end
		local function world(x, y)
			LPH_ATTRIBUTES(VM(NONE));
			local ray = camera:ViewportPointToRay(x, y)
			return ray.Origin + ray.Direction * 0.001
		end
		local topLeft, topRight, bottomRight = world(x0, y0), world(x1, y0), world(x1, y1)
		local cf = camera.CFrame
		part.CFrame = CFrame.fromMatrix((topLeft + bottomRight) / 2, cf.XVector, cf.YVector, cf.ZVector)
		mesh.Scale = Vector3.new((topRight - topLeft).Magnitude, (topRight - bottomRight).Magnitude, 0)
	end
	local conn = connect(RunService.RenderStepped, update)
	return {
		SetEnabled = function(_, on)
			LPH_ATTRIBUTES(VM(NONE));
			enabled = on
			folder.Parent = on and workspace.CurrentCamera or nil
			dof.Parent = on and Lighting or nil
			if on then
				update()
			end
		end,
		Destroy = function()
			LPH_ATTRIBUTES(VM(NONE));
			conn:Disconnect()
			folder:Destroy()
			dof:Destroy()
		end,
	}
end

local function createBlur(mode, target, strength)
	LPH_ATTRIBUTES(VM(NONE));
	if mode == false or mode == "None" then
		return nil
	end
	local wantGlass = mode == "Glass" or mode == "Both"
	local uiBlur, glass
	if mode ~= "Glass" then
		local ok, inst = pcall(Instance.new, "UIBlur")
		if ok and inst then
			pcall(function()
				LPH_ATTRIBUTES(VM(NONE));
				inst.Strength = Enum.UIBlurStrength[strength or "Medium"]
			end)
			inst.Parent = target
			uiBlur = inst
		elseif mode ~= "UIBlur" then
			wantGlass = true
		end
	end
	if wantGlass then
		local ok, handle = pcall(createGlassBlur, target)
		glass = ok and handle or nil
	end
	if not uiBlur and not glass then
		return nil
	end
	return {
		Kind = uiBlur and (glass and "Both" or "UIBlur") or "Glass",
		Instance = uiBlur,
		SetEnabled = function(_, on)
			LPH_ATTRIBUTES(VM(NONE));
			if uiBlur then
				uiBlur.Enabled = on
			end
			if glass then
				glass:SetEnabled(on)
			end
		end,
		Destroy = function()
			LPH_ATTRIBUTES(VM(NONE));
			if uiBlur then
				uiBlur:Destroy()
			end
			if glass then
				glass:Destroy()
			end
		end,
	}
end
---------------------------------------------------------------------
-- Popups (dropdown lists, colour pickers, card menus)
---------------------------------------------------------------------

local Popup = {}
Popup.__index = Popup

-- opts: Width, Height, Build(frame, popup) -> optional height, OnClose, Below
function Popup.open(window, anchor, opts)
	LPH_ATTRIBUTES(VM(NONE));
	if window._popupAnchor == anchor and os.clock() - (window._popupClosed or 0) < 0.2 then
		return nil
	end
	window:_closePopup()
	local scale = window._scale
	local overlay = window.PopupLayer
	local anchorPos = (anchor.AbsolutePosition - overlay.AbsolutePosition) / scale
	local anchorSize = anchor.AbsoluteSize / scale
	local area = overlay.AbsoluteSize / scale

	local self = setmetatable({ Window = window, Anchor = anchor, OnClose = opts.OnClose }, Popup)
	local catcher = new("TextButton", { Name = "PopupCatcher", Size = UDim2.fromScale(1, 1), ZIndex = 1, Parent = overlay })
	catcher.MouseButton1Down:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		window:_closePopup()
	end)
	self.Catcher = catcher

	local width = math.max(opts.Width or 0, 132)
	local frame = new("Frame", {
		Name = "Popup",
		Size = UDim2.fromOffset(width, 40),
		BackgroundTransparency = 0,
		Active = true,
		ZIndex = 2,
		Theme = { BackgroundColor3 = "Popup" },
		Parent = overlay,
	})
	pcall(function()
		LPH_ATTRIBUTES(VM(NONE));
		frame.InputSink = Enum.InputSink.All
	end)
	corner(frame, 10)
	local border = stroke(frame, nil, 1, 0)
	border.Color = WHITE
	gradient(border, 90, { "CardStrokeTop", "CardStrokeMid" })
	glow(frame, { Color = "Black", Blur = 22, Transparency = 0.45, Offset = Vector2.new(0, 8) })
	glow(frame, { Blur = 18, Transparency = 0.8 })
	self.Frame = frame

	local height = opts.Build(frame, self) or 40
	frame.Size = UDim2.fromOffset(width, height)

	local x = anchorPos.X + anchorSize.X - width
	local y = anchorPos.Y + anchorSize.Y + 5
	local below = true
	if y + height > area.Y - 6 then
		y = anchorPos.Y - height - 5
		below = false
	end
	x = math.clamp(x, 6, math.max(6, area.X - width - 6))
	y = math.clamp(y, 6, math.max(6, area.Y - height - 6))
	frame.Position = UDim2.fromOffset(round(x), round(y + (below and -6 or 6)))
	window._popup = self
	frame.Visible = false
	fade(frame, true, 0.16)
	tween(frame, 0.22, { Position = UDim2.fromOffset(round(x), round(y)) })
	return self
end

function Popup:ContainsPoint(point)
	LPH_ATTRIBUTES(VM(NONE));
	local f = self.Frame
	if not f or not f.Parent then
		return false
	end
	local p, s = f.AbsolutePosition, f.AbsoluteSize
	return point.X >= p.X and point.Y >= p.Y and point.X <= p.X + s.X and point.Y <= p.Y + s.Y
end

function Popup:Close()
	LPH_ATTRIBUTES(VM(NONE));
	if self.Closed then
		return
	end
	self.Closed = true
	self.Window._popupAnchor = self.Anchor
	self.Window._popupClosed = os.clock()
	self.Catcher:Destroy()
	local frame = self.Frame
	fade(frame, false, 0.12, function()
		LPH_ATTRIBUTES(VM(NONE));
		frame:Destroy()
	end)
	if self.OnClose then
		self.OnClose()
	end
end

-- A scrolling list of rows; items: { Text, Selected, Icon, Disabled, Callback(popup, index) -> keepOpen }
local function buildList(frame, popup, items, opts)
	LPH_ATTRIBUTES(VM(NONE));
	local ITEM = 28
	local search
	local top = 4
	if opts.Searchable then
		local box = new("Frame", {
			Name = "Search",
			Position = UDim2.fromOffset(6, 6),
			Size = UDim2.new(1, -12, 0, 26),
			BackgroundTransparency = 0,
			ZIndex = 3,
			Theme = { BackgroundColor3 = "Control" },
			Parent = frame,
		})
		corner(box, 8)
		stroke(box, "ControlStroke", 1, 0)
		icon("search", 12, "SubText", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 8, 0.5, 0), ZIndex = 3, Parent = box })
		search = new("TextBox", {
			Position = UDim2.fromOffset(26, 0),
			Size = UDim2.new(1, -32, 1, 0),
			FontFace = Fonts.Body,
			TextSize = 14,
			TextXAlignment = Enum.TextXAlignment.Left,
			PlaceholderText = "Search...",
			ClearTextOnFocus = false,
			Text = "",
			ZIndex = 3,
			Theme = { TextColor3 = "Text", PlaceholderColor3 = "Placeholder" },
			Parent = box,
		})
		top = 38
	end
	local visibleCount = math.min(#items, opts.MaxVisible or 8)
	local listHeight = math.max(1, visibleCount) * ITEM
	local list = new("ScrollingFrame", {
		Name = "Items",
		Position = UDim2.fromOffset(4, top),
		Size = UDim2.new(1, -8, 0, listHeight),
		BackgroundTransparency = 1,
		CanvasSize = UDim2.fromOffset(0, #items * ITEM),
		ScrollBarThickness = #items > visibleCount and 2 or 0,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ZIndex = 3,
		Theme = { ScrollBarImageColor3 = "AccentDeep" },
		Parent = frame,
	})
	local layout = new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = list })
	popup.Rows = {}
	for index, item in ipairs(items) do
		local row = new("TextButton", {
			Name = "Item",
			LayoutOrder = index,
			Size = UDim2.new(1, 0, 0, ITEM),
			BackgroundColor3 = WHITE,
			BackgroundTransparency = 1,
			ZIndex = 3,
			Parent = list,
		})
		corner(row, 7)
		local label = new("TextLabel", {
			Name = "Text",
			Position = UDim2.fromOffset(9, 0),
			Size = UDim2.new(1, -35, 1, 0),
			FontFace = Fonts.Label,
			TextSize = 15,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Text = item.Text,
			TextTransparency = item.Disabled and 0.5 or 0,
			ZIndex = 3,
			Parent = row,
		})
		local check = icon("check", 13, "Accent", {
			Name = "Check",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -8, 0.5, 0),
			Visible = item.Selected == true,
			ZIndex = 3,
			Parent = row,
		})
		local entry = { Row = row, Label = label, Check = check, Text = string.lower(item.Text) }
		local function color()
			LPH_ATTRIBUTES(VM(NONE));
			label.TextColor3 = entry.Selected and Theme.Accent or Theme.Text
		end
		entry.Selected = item.Selected == true
		color()
		row.MouseEnter:Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			tween(row, 0.12, { BackgroundTransparency = 0.93 })
		end)
		row.MouseLeave:Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			tween(row, 0.2, { BackgroundTransparency = 1 })
		end)
		row.MouseButton1Click:Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			if item.Disabled then
				return
			end
			local keepOpen = item.Callback and item.Callback(popup, index) == true
			if not keepOpen then
				popup.Window:_closePopup()
			end
		end)
		function entry.SetSelected(selected)
			LPH_ATTRIBUTES(VM(NONE));
			entry.Selected = selected
			check.Visible = selected
			color()
		end
		popup.Rows[index] = entry
	end
	if search then
		search:GetPropertyChangedSignal("Text"):Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			local query = string.lower(search.Text)
			local shown = 0
			for _, entry in ipairs(popup.Rows) do
				local hit = query == "" or string.find(entry.Text, query, 1, true) ~= nil
				entry.Row.Visible = hit
				if hit then
					shown += 1
				end
			end
			list.CanvasSize = UDim2.fromOffset(0, shown * ITEM)
			list.CanvasPosition = Vector2.new(0, 0)
		end)
		task.defer(function()
			LPH_ATTRIBUTES(VM(NONE));
			if search.Parent then
				search:CaptureFocus()
			end
		end)
	end
	if #items == 0 then
		new("TextLabel", {
			Position = UDim2.fromOffset(10, top),
			Size = UDim2.new(1, -20, 0, ITEM),
			FontFace = Fonts.Body,
			TextSize = 14,
			TextXAlignment = Enum.TextXAlignment.Left,
			Text = "No options",
			ZIndex = 3,
			Theme = { TextColor3 = "SubText" },
			Parent = frame,
		})
	end
	return top + listHeight + 4
end

---------------------------------------------------------------------
-- Elements and option registration
---------------------------------------------------------------------

local Element = {}
Element.__index = Element

function Element:SetVisible(visible)
	LPH_ATTRIBUTES(VM(NONE));
	self.Hidden = not visible
	if self.Container then
		self.Container.Visible = visible and not self._filtered
	end
end

function Element:Matches(query)
	LPH_ATTRIBUTES(VM(NONE));
	if query == "" then
		return true
	end
	return string.find(string.lower(self.SearchText or ""), query, 1, true) ~= nil
end

local orderCounter = 0
local function nextOrder()
	LPH_ATTRIBUTES(VM(NONE));
	orderCounter += 1
	return orderCounter
end

local function makeRow(card, name, height)
	LPH_ATTRIBUTES(VM(NONE));
	local row = new("Frame", {
		Name = tostring(name),
		LayoutOrder = nextOrder(),
		Size = UDim2.new(1, 0, 0, height),
		BackgroundColor3 = WHITE,
		BackgroundTransparency = 1,
		Parent = card.Body,
	})
	local divider = new("Frame", {
		Name = "Divider",
		Size = UDim2.new(1, 0, 0, 1),
		BackgroundTransparency = 0.25,
		Theme = { BackgroundColor3 = "Divider" },
		Parent = row,
	})
	row.MouseEnter:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(row, 0.15, { BackgroundTransparency = 0.965 })
	end)
	row.MouseLeave:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(row, 0.3, { BackgroundTransparency = 1 })
	end)
	local element = setmetatable({ Container = row, Divider = divider, SearchText = tostring(name), Card = card }, Element)
	table.insert(card.Elements, element)
	if card.Window then
		table.insert(card.Window.Elements, element)
	end
	return row, element
end

local function rowLabel(row, text, props)
	LPH_ATTRIBUTES(VM(NONE));
	local label = new("TextLabel", {
		Name = "Label",
		Position = UDim2.fromOffset(7, 0),
		Size = UDim2.new(1, -14, 1, 0),
		FontFace = Fonts.Label,
		TextSize = 16,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Text = tostring(text),
		Theme = { TextColor3 = "Text" },
		Parent = row,
	})
	if props then
		for key, value in pairs(props) do
			label[key] = value
		end
	end
	return label
end

local function sanitizeId(text)
	LPH_ATTRIBUTES(VM(NONE));
	return (string.gsub(tostring(text or "Option"), "[^%w_%-%.]", "_"))
end

local OptionMethods = {}

function OptionMethods:OnChanged(fn)
	LPH_ATTRIBUTES(VM(NONE));
	if type(fn) == "function" then
		table.insert(self._listeners, fn)
	end
	return self
end

function OptionMethods:RunChanged()
	LPH_ATTRIBUTES(VM(NONE));
	fire(self.Callback, self.Value)
	for _, fn in ipairs(self._listeners) do
		fire(fn, self.Value)
	end
	return self
end

function OptionMethods:SetVisible(visible)
	LPH_ATTRIBUTES(VM(NONE));
	if self._element then
		self._element:SetVisible(visible)
	end
	self.Visible = visible ~= false
	return self
end

function OptionMethods:SetDisabled(disabled)
	LPH_ATTRIBUTES(VM(NONE));
	self.Disabled = disabled == true
	local row = self._element and self._element.Container
	if row then
		for _, child in ipairs(row:GetDescendants()) do
			if child:IsA("TextLabel") or child:IsA("TextBox") then
				child.TextTransparency = self.Disabled and 0.5 or 0
			end
		end
	end
	return self
end

function OptionMethods:SetText(text)
	LPH_ATTRIBUTES(VM(NONE));
	self.Text = tostring(text)
	self.DisplayName = self.Text
	if self._label then
		self._label.Text = self.Text
	end
	if self._element then
		self._element.SearchText = self.Text
	end
	return self
end

-- Adds the common option surface and files the option under its id.
local function register(card, api, optionType, id, displayName, info)
	LPH_ATTRIBUTES(VM(NONE));
	local window = card.Window
	local registry = optionType == "Toggle" and Library.Toggles or Library.Options
	local base = sanitizeId(id or ((card.Tab and card.Tab.Name or "Tab") .. "." .. tostring(card.Title or "Card") .. "." .. tostring(displayName)))
	local final, n = base, 2
	while registry[final] and registry[final] ~= api do
		final = base .. "_" .. n
		n += 1
	end
	api.Id = final
	api.Idx = final
	api.Type = optionType
	api.Text = displayName
	api.DisplayName = displayName
	api.NoSave = info and info.NoSave == true or false
	api.Callback = info and info.Callback or nil
	api.Tooltip = info and info.Tooltip or nil
	api.Visible = true
	api._listeners = api._listeners or {}
	api._card = card
	api._window = window
	for name, fn in pairs(OptionMethods) do
		if api[name] == nil then
			api[name] = fn
		end
	end
	api.SetValue = api.SetValue or api.Set
	api.Set = api.Set or api.SetValue
	registry[final] = api
	if api._element then
		api._element.ValueObject = api
	end
	if api.Tooltip and api._element and window then
		window:_attachTooltip(api._element.Container, api.Tooltip)
	end
	return api
end

local function changed(api, silent)
	LPH_ATTRIBUTES(VM(NONE));
	if silent then
		return
	end
	fire(api.Callback, api.Value)
	for _, fn in ipairs(api._listeners) do
		fire(fn, api.Value)
	end
end

---------------------------------------------------------------------
-- Inline addons: key chip and colour swatch
---------------------------------------------------------------------

local Card = {}
Card.__index = Card

local function addonHolder(row)
	LPH_ATTRIBUTES(VM(NONE));
	local holder = row:FindFirstChild("Addons")
	if holder then
		return holder
	end
	holder = new("Frame", {
		Name = "Addons",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -7, 0.5, 0),
		Size = UDim2.fromOffset(0, 26),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		ZIndex = 2,
		Parent = row,
	})
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Right,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = px(6),
		Parent = holder,
	})
	return holder
end

-- Key picker. `row` is where it lives; `inline` makes it a compact chip.
local function createKeyPicker(card, row, element, id, info, inline)
	LPH_ATTRIBUTES(VM(NONE));
	info = info or {}
	local window = card.Window
	local display = info.Text or tostring(id)
	local modes = info.Modes or { "Toggle", "Hold", "Always" }
	local mode = info.Mode or modes[1] or "Toggle"
	if not table.find(modes, mode) then
		table.insert(modes, mode)
	end
	local value = stringToEnum(info.Default or "None")
	local api = { ShowInList = info.NoUI ~= true, Modifiers = info.Modifiers or {}, _element = element }
	api.Toggled = mode == "Always"

	local holder = addonHolder(row)
	local chip = new("TextButton", {
		Name = "Key",
		LayoutOrder = 1,
		Size = UDim2.fromOffset(0, inline and 22 or 26),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 0,
		FontFace = inline and Fonts.Strong or Fonts.Label,
		TextSize = inline and 13 or 15,
		Text = "",
		Theme = { BackgroundColor3 = "Control", TextColor3 = "Text" },
		Parent = holder,
	})
	corner(chip, inline and 8 or 12)
	local chipStroke = stroke(chip, "ControlStroke", 1, 0)
	new("UIPadding", { PaddingLeft = px(inline and 8 or 12), PaddingRight = px(inline and 8 or 12), Parent = chip })
	new("UISizeConstraint", { MinSize = Vector2.new(inline and 30 or 64, 0), Parent = chip })
	local modeChip
	if not inline and #modes > 1 then
		modeChip = new("TextButton", {
			Name = "Mode",
			LayoutOrder = 2,
			Size = UDim2.fromOffset(0, 26),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 0,
			FontFace = Fonts.Strong,
			TextSize = 13,
			Text = mode,
			Theme = { BackgroundColor3 = "Control", TextColor3 = "SubText" },
			Parent = holder,
		})
		corner(modeChip, 12)
		stroke(modeChip, "ControlStroke", 1, 0)
		new("UIPadding", { PaddingLeft = px(10), PaddingRight = px(10), Parent = modeChip })
	end

	local listening = false
	local function render()
		LPH_ATTRIBUTES(VM(NONE));
		if listening then
			chip.Text = "..."
			return
		end
		chip.Text = value == KEY_NONE and (inline and "—" or "None") or keyLabel(value)
		if modeChip then
			modeChip.Text = mode
		end
	end

	function api:Get()
		LPH_ATTRIBUTES(VM(NONE));
		return value
	end
	function api:GetMode()
		LPH_ATTRIBUTES(VM(NONE));
		return mode
	end
	function api:IsActive()
		LPH_ATTRIBUTES(VM(NONE));
		return mode == "Always" or (value ~= KEY_NONE and self.Toggled == true)
	end
	function api:GetState()
		LPH_ATTRIBUTES(VM(NONE));
		return self:IsActive()
	end
	local function sync()
		LPH_ATTRIBUTES(VM(NONE));
		api.Value = enumToString(value)
		api.Mode = mode
	end
	function api:SetActive(active, silent)
		LPH_ATTRIBUTES(VM(NONE));
		local before = self.Toggled
		self.Toggled = mode == "Always" or (value ~= KEY_NONE and active == true)
		if not silent then
			if info.SyncToggleState and self._parentToggle then
				self._parentToggle:SetValue(self.Toggled)
			end
			fire(info.Callback, self.Toggled, value, mode)
			if before ~= self.Toggled then
				fire(info.Clicked, self.Toggled)
			end
		end
		window:_refreshKeybinds()
		return self
	end
	function api:SetMode(newMode, silent)
		LPH_ATTRIBUTES(VM(NONE));
		if not table.find(modes, newMode) then
			return self
		end
		mode = newMode
		sync()
		render()
		self.Toggled = mode == "Always" or (mode == "Toggle" and self.Toggled == true)
		if not silent then
			fire(info.ChangedCallback, value, mode)
			changed(self, false)
		end
		window:_refreshKeybinds()
		return self
	end
	function api:Set(v, silent)
		LPH_ATTRIBUTES(VM(NONE));
		if type(v) == "table" then
			local key, newMode, modifiers = v[1] or v.Key, v[2] or v.Mode, v[3] or v.Modifiers
			if key ~= nil then
				value = stringToEnum(key)
			end
			if newMode and table.find(modes, newMode) then
				mode = newMode
			end
			if type(modifiers) == "table" then
				self.Modifiers = modifiers
			end
		else
			value = stringToEnum(v)
		end
		if mode ~= "Always" and mode ~= "Toggle" then
			self.Toggled = false
		end
		sync()
		render()
		if not silent then
			fire(info.ChangedCallback, value, mode)
			changed(self, false)
		end
		window:_refreshKeybinds()
		return self
	end
	api.SetValue = api.Set
	function api:Update()
		LPH_ATTRIBUTES(VM(NONE));
		if mode == "Always" then
			self.Toggled = true
		elseif value == KEY_NONE then
			self.Toggled = false
		end
		sync()
		render()
		window:_refreshKeybinds()
		return self
	end
	function api:DoClick()
		LPH_ATTRIBUTES(VM(NONE));
		if mode == "Toggle" then
			self:SetActive(not self.Toggled)
		elseif mode == "Always" then
			fire(info.Callback, true, value, mode)
		end
	end
	-- key events routed by the window
	function api:_input(input, began)
		LPH_ATTRIBUTES(VM(NONE));
		if not inputMatches(input, value) then
			return
		end
		if began then
			if mode == "Toggle" then
				self:SetActive(not self.Toggled)
			elseif mode == "Hold" then
				self:SetActive(true)
			elseif mode == "Always" then
				fire(info.Callback, true, value, mode)
			end
		elseif mode == "Hold" then
			self:SetActive(false)
		end
	end
	function api:_release()
		LPH_ATTRIBUTES(VM(NONE));
		if mode == "Hold" and self.Toggled then
			self:SetActive(false)
		end
	end

	local function capture()
		LPH_ATTRIBUTES(VM(NONE));
		if listening then
			return
		end
		window:_closePopup()
		listening = true
		window._capturing = api
		render()
		tween(chipStroke, 0.15, { Color = Theme.Accent })
		local armed = false
		task.delay(0.12, function()
			LPH_ATTRIBUTES(VM(NONE));
			armed = true
		end)
		local conn
		conn = connect(UserInputService.InputBegan, function(input)
			LPH_ATTRIBUTES(VM(NONE));
			if not armed then
				return
			end
			local picked
			if input.UserInputType == Enum.UserInputType.Keyboard then
				if input.KeyCode == Enum.KeyCode.Escape then
					picked = value
				elseif input.KeyCode == Enum.KeyCode.Backspace then
					picked = KEY_NONE
				else
					picked = input.KeyCode
				end
			elseif input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.MouseButton2
				or input.UserInputType == Enum.UserInputType.MouseButton3 then
				picked = input.UserInputType
			else
				return
			end
			conn:Disconnect()
			listening = false
			task.defer(function()
				LPH_ATTRIBUTES(VM(NONE));
				if window._capturing == api then
					window._capturing = nil
				end
			end)
			tween(chipStroke, 0.25, { Color = Theme.ControlStroke })
			if picked ~= value then
				api:Set(picked)
			else
				render()
			end
		end)
	end

	local function openModes(anchor)
		LPH_ATTRIBUTES(VM(NONE));
		local items = {}
		for _, m in ipairs(modes) do
			table.insert(items, {
				Text = m,
				Selected = m == mode,
				Callback = function()
					LPH_ATTRIBUTES(VM(NONE));
					api:SetMode(m)
				end,
			})
		end
		Popup.open(window, anchor, {
			Width = 120,
			Build = function(frame, popup)
				LPH_ATTRIBUTES(VM(NONE));
				return buildList(frame, popup, items, {})
			end,
		})
	end

	chip.MouseButton1Click:Connect(capture)
	chip.MouseButton2Click:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		if #modes > 1 then
			openModes(chip)
		end
	end)
	if modeChip then
		modeChip.MouseButton1Click:Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			openModes(modeChip)
		end)
	end
	chip.MouseEnter:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		if not listening then
			tween(chipStroke, 0.15, { Color = Theme.AccentDeep })
		end
	end)
	chip.MouseLeave:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		if not listening then
			tween(chipStroke, 0.25, { Color = Theme.ControlStroke })
		end
	end)
	if inline and #modes > 1 then
		window:_attachTooltip(chip, "Click to rebind, right-click for mode")
	end

	sync()
	render()
	register(card, api, "KeyPicker", id, display, info)
	api.Callback = nil -- the key callback has its own signature, fired by SetActive
	api.KeyCallback = info.Callback
	table.insert(window.Keybinds, api)
	window:_refreshKeybinds()
	return api
end

local function hexOf(color)
	LPH_ATTRIBUTES(VM(NONE));
	return string.format("#%02X%02X%02X", round(color.R * 255), round(color.G * 255), round(color.B * 255))
end

local function parseHex(text)
	LPH_ATTRIBUTES(VM(NONE));
	local hex = string.gsub(tostring(text or ""), "[^%x]", "")
	if #hex == 3 then
		hex = string.gsub(hex, "%x", "%0%0")
	end
	if #hex ~= 6 then
		return nil
	end
	return Color3.fromRGB(tonumber(string.sub(hex, 1, 2), 16), tonumber(string.sub(hex, 3, 4), 16), tonumber(string.sub(hex, 5, 6), 16))
end

local function createColorPicker(card, row, element, id, info, inline)
	LPH_ATTRIBUTES(VM(NONE));
	info = info or {}
	local window = card.Window
	local display = info.Title or info.Text or tostring(id)
	local color = typeof(info.Default) == "Color3" and info.Default or Theme.Accent
	local h, s, v = color:ToHSV()
	local hasAlpha = info.Transparency ~= nil
	local api = { Transparency = tonumber(info.Transparency) or 0, _element = element }

	local holder = addonHolder(row)
	local swatch = new("TextButton", {
		Name = "Color",
		LayoutOrder = 3,
		Size = UDim2.fromOffset(inline and 26 or 34, inline and 18 or 22),
		BackgroundTransparency = 0,
		Parent = holder,
	})
	corner(swatch, 6)
	stroke(swatch, "ControlStroke", 1, 0)
	local swatchGlow = glow(swatch, { Blur = 6, Transparency = 0.7 })

	local popupRefs
	local function render(silent)
		LPH_ATTRIBUTES(VM(NONE));
		color = Color3.fromHSV(h, s, v)
		api.Value = color
		swatch.BackgroundColor3 = color
		swatch.BackgroundTransparency = math.clamp(api.Transparency, 0, 0.85)
		if swatchGlow.Instance then
			swatchGlow.Instance.Color = color
		end
		if popupRefs then
			popupRefs.sv.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
			popupRefs.cursor.Position = UDim2.fromScale(s, 1 - v)
			popupRefs.hueCursor.Position = UDim2.new(0.5, 0, h, 0)
			if popupRefs.hex and not popupRefs.hex:IsFocused() then
				popupRefs.hex.Text = hexOf(color)
			end
			if popupRefs.alphaCursor then
				popupRefs.alphaCursor.Position = UDim2.new(api.Transparency, 0, 0.5, 0)
				popupRefs.alphaFill.BackgroundColor3 = color
			end
		end
		changed(api, silent)
	end

	function api:Get()
		LPH_ATTRIBUTES(VM(NONE));
		return color
	end
	function api:Set(newColor, silent)
		LPH_ATTRIBUTES(VM(NONE));
		if typeof(newColor) == "Color3" then
			h, s, v = newColor:ToHSV()
		elseif type(newColor) == "table" then
			h, s, v = newColor[1] or newColor.H or h, newColor[2] or newColor.S or s, newColor[3] or newColor.V or v
		else
			return self
		end
		render(silent)
		return self
	end
	api.SetValue = api.Set
	function api:SetValueRGB(newColor, transparency)
		LPH_ATTRIBUTES(VM(NONE));
		if transparency ~= nil then
			self.Transparency = tonumber(transparency) or self.Transparency
		end
		return self:Set(newColor)
	end
	function api:SetHSV(hh, ss, vv)
		LPH_ATTRIBUTES(VM(NONE));
		h, s, v = hh, ss, vv
		render(false)
		return self
	end

	local dragging
	local function open()
		LPH_ATTRIBUTES(VM(NONE));
		popupRefs = nil
		Popup.open(window, swatch, {
			Width = 214,
			OnClose = function()
				LPH_ATTRIBUTES(VM(NONE));
				popupRefs = nil
				dragging = nil
			end,
			Build = function(frame)
				LPH_ATTRIBUTES(VM(NONE));
				local refs = {}
				new("TextLabel", {
					Position = UDim2.fromOffset(12, 8),
					Size = UDim2.new(1, -24, 0, 18),
					FontFace = Fonts.Strong,
					TextSize = 14,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					Text = display,
					ZIndex = 3,
					Theme = { TextColor3 = "Text" },
					Parent = frame,
				})
				local sv = new("TextButton", { Position = UDim2.fromOffset(12, 32), Size = UDim2.fromOffset(160, 120), BackgroundTransparency = 0, ZIndex = 3, Parent = frame })
				corner(sv, 6)
				local white = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = WHITE, BackgroundTransparency = 0, ZIndex = 3, Parent = sv })
				corner(white, 6)
				new("UIGradient", { Transparency = numberSeq(0, 0, 1, 1), Parent = white })
				local black = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = BLACK, BackgroundTransparency = 0, ZIndex = 3, Parent = sv })
				corner(black, 6)
				new("UIGradient", { Rotation = 90, Transparency = numberSeq(0, 1, 1, 0), Parent = black })
				local cursor = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(10, 10), BackgroundColor3 = WHITE, BackgroundTransparency = 0, ZIndex = 4, Parent = sv })
				corner(cursor, 5)
				local cs = stroke(cursor, nil, 1.5, 0.1)
				cs.Color = BLACK
				local hue = new("TextButton", { Position = UDim2.fromOffset(182, 32), Size = UDim2.fromOffset(20, 120), BackgroundColor3 = WHITE, BackgroundTransparency = 0, ZIndex = 3, Parent = frame })
				corner(hue, 6)
				local hueKeys = {}
				for i = 0, 6 do
					table.insert(hueKeys, ColorSequenceKeypoint.new(i / 6, Color3.fromHSV((i / 6) % 1, 1, 1)))
				end
				new("UIGradient", { Rotation = 90, Color = ColorSequence.new(hueKeys), Parent = hue })
				local hueCursor = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.new(1, 4, 0, 3), BackgroundColor3 = WHITE, BackgroundTransparency = 0, ZIndex = 4, Parent = hue })
				corner(hueCursor, 2)
				local y = 160
				local alpha
				if hasAlpha then
					alpha = new("TextButton", { Position = UDim2.fromOffset(12, y), Size = UDim2.fromOffset(190, 12), BackgroundColor3 = WHITE, BackgroundTransparency = 0, ZIndex = 3, Parent = frame })
					corner(alpha, 6)
					local fill = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 0, ZIndex = 3, Parent = alpha })
					corner(fill, 6)
					new("UIGradient", { Transparency = numberSeq(0, 0, 1, 1), Parent = fill })
					refs.alphaFill = fill
					refs.alphaCursor = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(4, 16), BackgroundColor3 = WHITE, BackgroundTransparency = 0, ZIndex = 4, Parent = alpha })
					corner(refs.alphaCursor, 2)
					y += 20
				end
				local hexBox = new("Frame", { Position = UDim2.fromOffset(12, y), Size = UDim2.fromOffset(190, 26), BackgroundTransparency = 0, ZIndex = 3, Theme = { BackgroundColor3 = "Control" }, Parent = frame })
				corner(hexBox, 8)
				stroke(hexBox, "ControlStroke", 1, 0)
				local hex = new("TextBox", {
					Position = UDim2.fromOffset(10, 0),
					Size = UDim2.new(1, -20, 1, 0),
					FontFace = Fonts.Mono,
					TextSize = 14,
					ClearTextOnFocus = false,
					Text = hexOf(color),
					ZIndex = 3,
					Theme = { TextColor3 = "Text" },
					Parent = hexBox,
				})
				hex.FocusLost:Connect(function()
					LPH_ATTRIBUTES(VM(NONE));
					local parsed = parseHex(hex.Text)
					if parsed then
						api:Set(parsed)
					else
						hex.Text = hexOf(color)
					end
				end)
				refs.sv, refs.cursor, refs.hueCursor, refs.hex = sv, cursor, hueCursor, hex
				local function begin(target, kind)
					LPH_ATTRIBUTES(VM(NONE));
					target.InputBegan:Connect(function(input)
						LPH_ATTRIBUTES(VM(NONE));
						if isPress(input) then
							dragging = kind
							window:_beginDrag(function(position)
								LPH_ATTRIBUTES(VM(NONE));
								if kind == "sv" then
									s = math.clamp((position.X - sv.AbsolutePosition.X) / math.max(sv.AbsoluteSize.X, 1), 0, 1)
									v = 1 - math.clamp((position.Y - sv.AbsolutePosition.Y) / math.max(sv.AbsoluteSize.Y, 1), 0, 1)
								elseif kind == "hue" then
									h = math.clamp((position.Y - hue.AbsolutePosition.Y) / math.max(hue.AbsoluteSize.Y, 1), 0, 0.999)
								else
									api.Transparency = math.clamp((position.X - alpha.AbsolutePosition.X) / math.max(alpha.AbsoluteSize.X, 1), 0, 1)
								end
								render(false)
							end, function()
								LPH_ATTRIBUTES(VM(NONE));
								dragging = nil
							end)
							window._drag.Move(input.Position)
						end
					end)
				end
				begin(sv, "sv")
				begin(hue, "hue")
				if alpha then
					begin(alpha, "alpha")
				end
				popupRefs = refs
				render(true)
				return y + 36
			end,
		})
	end
	swatch.MouseButton1Click:Connect(open)
	function api:Close()
		LPH_ATTRIBUTES(VM(NONE));
		window:_closePopup()
	end
	render(true)
	register(card, api, "ColorPicker", id, display, info)
	return api
end
---------------------------------------------------------------------
-- Card controls (shared by groupboxes, dependency boxes, tabbox pages, dialogs)
---------------------------------------------------------------------

local function cardChanged(card)
	LPH_ATTRIBUTES(VM(NONE));
	if card._host then
		card._host:Resize()
	elseif card.Resize then
		card:Resize()
	end
end

-- Toggle -------------------------------------------------------------

function Card:AddToggle(id, info, legacyCallback)
	LPH_ATTRIBUTES(VM(NONE));
	local display, explicit
	if type(info) == "table" then
		display, explicit = info.Text or tostring(id), id
	else
		display = tostring(id)
		info = { Text = display, Default = info, Callback = legacyCallback }
	end
	local default = info.Default == true
	if self.Window and self.Window.FeatureDefaultsOff then
		default = false
	end
	local row, element = makeRow(self, display, 35)
	element.SearchText = display
	local label = rowLabel(row, display, { Size = UDim2.new(1, -60, 1, 0) })
	if info.Risky then
		paint(label, { TextColor3 = "Risk" })
	end

	local switch = new("Frame", {
		Name = "Track",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -7, 0.5, 0),
		Size = UDim2.fromOffset(32, 18),
		BackgroundTransparency = 0,
		Theme = { BackgroundColor3 = "Control" },
		Parent = row,
	})
	corner(switch, 9)
	local border = stroke(switch, "ControlStroke", 1, 0)
	local fill = new("Frame", { Name = "On", Size = UDim2.fromScale(1, 1), BackgroundColor3 = WHITE, BackgroundTransparency = 1, Parent = switch })
	corner(fill, 9)
	gradient(fill, 0, { "ToggleA", "ToggleB" })
	local halo = glow(fill, { Blur = 10, Transparency = 1 })
	local knob = new("Frame", {
		Name = "Knob",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 2, 0.5, 0),
		Size = UDim2.fromOffset(14, 14),
		BackgroundTransparency = 0,
		ZIndex = 2,
		Theme = { BackgroundColor3 = "Knob" },
		Parent = switch,
	})
	corner(knob, 7)
	glow(knob, { Color = "Black", Blur = 4, Transparency = 0.7, Offset = Vector2.new(0, 1) })
	local hit = new("TextButton", { Name = "Hit", Size = UDim2.new(1, -110, 1, 0), Position = UDim2.fromOffset(0, 0), ZIndex = 1, Parent = row })
	local hitSwitch = new("TextButton", { Name = "HitSwitch", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 0), Size = UDim2.new(0, 46, 1, 0), ZIndex = 3, Parent = row })

	-- addons sit left of the switch
	local holder = addonHolder(row)
	holder.Position = UDim2.new(1, -46, 0.5, 0)

	local api = { _element = element, _label = label, Addons = {} }
	local ready = false
	local function render()
		LPH_ATTRIBUTES(VM(NONE));
		local on = api.Value
		local time = ready and 0.28 or 0
		local knobPos = UDim2.new(0, on and 16 or 2, 0.5, 0)
		if ready then
			tween(knob, time, { Position = knobPos, Size = UDim2.fromOffset(14, 14) }, Enum.EasingStyle.Back)
			tween(fill, 0.2, { BackgroundTransparency = on and 0 or 1 })
			tween(border, 0.2, { Transparency = on and 1 or 0 })
			if not info.Risky then
				tween(label, 0.2, { TextColor3 = on and Theme.Text or Theme.TextOff })
			end
		else
			knob.Position = knobPos
			fill.BackgroundTransparency = on and 0 or 1
			border.Transparency = on and 1 or 0
			if not info.Risky then
				label.TextColor3 = on and Theme.Text or Theme.TextOff
			end
		end
		setGlow(halo, on and 0.45 or 1, time)
	end
	if not info.Risky then
		onTheme(function()
			LPH_ATTRIBUTES(VM(NONE));
			if ready then
				label.TextColor3 = api.Value and Theme.Text or Theme.TextOff
			end
		end)
	end

	function api:Get()
		LPH_ATTRIBUTES(VM(NONE));
		return self.Value
	end
	function api:Set(value, silent)
		LPH_ATTRIBUTES(VM(NONE));
		value = value == true
		self.Value = value
		render()
		for _, addon in ipairs(self.Addons) do
			if addon.Type == "KeyPicker" and addon._syncToggle and addon.Toggled ~= value then
				addon:SetActive(value, true)
			end
		end
		if self.Disabled and not silent then
			return self
		end
		changed(self, silent)
		return self
	end
	api.SetValue = api.Set

	local function click()
		LPH_ATTRIBUTES(VM(NONE));
		if api.Disabled then
			return
		end
		api:Set(not api.Value)
	end
	hit.MouseButton1Click:Connect(click)
	hitSwitch.MouseButton1Down:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(knob, 0.12, { Size = UDim2.fromOffset(18, 14), Position = UDim2.new(0, api.Value and 12 or 2, 0.5, 0) })
	end)
	hitSwitch.MouseButton1Click:Connect(click)
	hitSwitch.MouseLeave:Connect(render)

	function api:AddKeyPicker(keyId, keyInfo)
		LPH_ATTRIBUTES(VM(NONE));
		keyInfo = keyInfo or {}
		local picker = createKeyPicker(self._card, row, element, keyId, keyInfo, true)
		picker._parentToggle = self
		picker._syncToggle = keyInfo.SyncToggleState == true
		table.insert(self.Addons, picker)
		if picker._syncToggle then
			picker:SetActive(self.Value, true)
		end
		return picker
	end
	function api:AddColorPicker(colorId, colorInfo)
		LPH_ATTRIBUTES(VM(NONE));
		colorInfo = colorInfo or {}
		if colorInfo.Title == nil and colorInfo.Text == nil then
			colorInfo.Title = display
		end
		local picker = createColorPicker(self._card, row, element, colorId, colorInfo, true)
		table.insert(self.Addons, picker)
		return picker
	end

	api.Value = default
	api.Default = default
	render()
	ready = true
	register(self, api, "Toggle", explicit, display, info)
	return api
end

-- Slider -------------------------------------------------------------

function Card:AddSlider(id, info, max, default, step, legacyCallback)
	LPH_ATTRIBUTES(VM(NONE));
	local display, explicit
	if type(info) == "table" then
		display, explicit = info.Text or tostring(id), id
	else
		display = tostring(id)
		info = { Text = display, Min = info, Max = max, Default = default, Callback = legacyCallback }
		if step then
			info.Rounding = math.max(0, math.ceil(-math.log10(step) - 1e-9))
		end
	end
	local min = tonumber(info.Min) or 0
	local maxValue = tonumber(info.Max) or 100
	local rounding = tonumber(info.Rounding) or 0
	local suffix = tostring(info.Suffix or "")
	local row, element = makeRow(self, display, 41)
	local api = { _element = element, Min = min, Max = maxValue, Rounding = rounding, Suffix = suffix }

	local line = new("Frame", { Name = "Line", Position = UDim2.fromOffset(0, 1), Size = UDim2.new(1, 0, 1, -1), BackgroundTransparency = 1, Parent = row })
	new("UIPadding", { PaddingLeft = px(7), PaddingRight = px(7), Parent = line })
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = line,
	})
	local label = rowLabel(line, display, { Position = UDim2.new(), Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, LayoutOrder = 1, TextTruncate = Enum.TextTruncate.None })
	new("UISizeConstraint", { MaxSize = Vector2.new(172, math.huge), Parent = label })
	label.TextTruncate = Enum.TextTruncate.AtEnd
	api._label = label
	new("Frame", { Name = "Gap", LayoutOrder = 2, Size = UDim2.fromOffset(13, 1), BackgroundTransparency = 1, Parent = line })
	local trackFrame = new("TextButton", {
		Name = "Track",
		LayoutOrder = 3,
		Size = UDim2.fromOffset(60, 18),
		BackgroundTransparency = 0,
		Theme = { BackgroundColor3 = "Control" },
		Parent = line,
	})
	new("UIFlexItem", { FlexMode = Enum.UIFlexMode.Fill, Parent = trackFrame })
	corner(trackFrame, 9)
	stroke(trackFrame, "ControlStroke", 1, 0)
	local fillFrame = new("Frame", { Name = "Fill", Size = UDim2.new(0, 9, 1, 0), BackgroundColor3 = WHITE, BackgroundTransparency = 0, Parent = trackFrame })
	corner(fillFrame, 9)
	gradient(fillFrame, 0, { "AccentDeep", "SliderB" })
	local knob = new("Frame", {
		Name = "Knob",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0, 9, 0.5, 0),
		Size = UDim2.fromOffset(14, 14),
		BackgroundTransparency = 0,
		ZIndex = 2,
		Theme = { BackgroundColor3 = "Knob" },
		Parent = trackFrame,
	})
	corner(knob, 7)
	local halo = glow(knob, { Blur = 9, Transparency = 0.5 })
	new("Frame", { Name = "Gap", LayoutOrder = 4, Size = UDim2.fromOffset(8, 1), BackgroundTransparency = 1, Parent = line })
	local box = new("Frame", {
		Name = "Value",
		LayoutOrder = 5,
		Size = UDim2.fromOffset(0, 23),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 0,
		Theme = { BackgroundColor3 = "Control" },
		Parent = line,
	})
	new("UISizeConstraint", { MinSize = Vector2.new(54, 23), Parent = box })
	new("UIPadding", { PaddingLeft = px(8), PaddingRight = px(8), Parent = box })
	corner(box, 10)
	local boxBorder = stroke(box, "ControlStroke", 1, 0)
	local input = new("TextBox", {
		Name = "Input",
		Size = UDim2.new(0, 0, 1, 0),
		AutomaticSize = Enum.AutomaticSize.X,
		FontFace = Fonts.Mono,
		TextSize = 15,
		TextXAlignment = Enum.TextXAlignment.Right,
		ClearTextOnFocus = false,
		Text = "",
		Theme = { TextColor3 = "Text" },
		Parent = box,
	})
	new("UISizeConstraint", { MinSize = Vector2.new(38, 0), Parent = input })

	local function format(value)
		LPH_ATTRIBUTES(VM(NONE));
		local text = string.format("%." .. math.max(0, rounding) .. "f", value)
		return text .. suffix
	end
	local function quantize(value)
		LPH_ATTRIBUTES(VM(NONE));
		local mult = 10 ^ rounding
		value = math.floor(value * mult + 0.5) / mult
		return math.clamp(value, api.Min, api.Max)
	end
	local function layout(animated)
		LPH_ATTRIBUTES(VM(NONE));
		local scale = self.Window and self.Window._scale or 1
		local width = trackFrame.AbsoluteSize.X / scale
		if width <= 0 then
			return
		end
		local range = api.Max - api.Min
		local frac = range > 0 and (api.Value - api.Min) / range or 0
		local center = math.clamp(frac * width, 9, math.max(9, width - 9))
		if animated then
			tween(knob, 0.12, { Position = UDim2.new(0, center, 0.5, 0) }, Enum.EasingStyle.Quad)
			tween(fillFrame, 0.12, { Size = UDim2.new(0, center, 1, 0) }, Enum.EasingStyle.Quad)
		else
			knob.Position = UDim2.new(0, center, 0.5, 0)
			fillFrame.Size = UDim2.new(0, center, 1, 0)
		end
	end

	local ready = false
	function api:Get()
		LPH_ATTRIBUTES(VM(NONE));
		return self.Value
	end
	function api:Set(value, silent)
		LPH_ATTRIBUTES(VM(NONE));
		local number = tonumber(value)
		if number == nil or number ~= number then
			return self
		end
		self.Value = quantize(number)
		input.Text = format(self.Value)
		layout(ready)
		changed(self, silent)
		return self
	end
	api.SetValue = api.Set
	function api:SetMin(value)
		LPH_ATTRIBUTES(VM(NONE));
		self.Min = tonumber(value) or self.Min
		self:Set(math.max(self.Value, self.Min), true)
		return self
	end
	function api:SetMax(value)
		LPH_ATTRIBUTES(VM(NONE));
		self.Max = tonumber(value) or self.Max
		self:Set(math.min(self.Value, self.Max), true)
		return self
	end
	function api:SetSuffix(value)
		LPH_ATTRIBUTES(VM(NONE));
		suffix = tostring(value or "")
		self.Suffix = suffix
		input.Text = format(self.Value)
		return self
	end

	trackFrame:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		layout(false)
	end)
	local function fromX(x)
		LPH_ATTRIBUTES(VM(NONE));
		local width = trackFrame.AbsoluteSize.X
		if width <= 0 or api.Disabled then
			return
		end
		local frac = math.clamp((x - trackFrame.AbsolutePosition.X) / width, 0, 1)
		local value = quantize(api.Min + frac * (api.Max - api.Min))
		if value ~= api.Value then
			api:Set(value)
		end
	end
	local function setActive(active)
		LPH_ATTRIBUTES(VM(NONE));
		tween(knob, 0.18, { Size = active and UDim2.fromOffset(16, 16) or UDim2.fromOffset(14, 14) })
		setGlow(halo, active and 0.15 or 0.5, 0.18)
	end
	trackFrame.InputBegan:Connect(function(inputObject)
		LPH_ATTRIBUTES(VM(NONE));
		if isPress(inputObject) and self.Window then
			setActive(true)
			fromX(inputObject.Position.X)
			self.Window:_beginDrag(function(position)
				LPH_ATTRIBUTES(VM(NONE));
				fromX(position.X)
			end, function()
				LPH_ATTRIBUTES(VM(NONE));
				setActive(false)
			end)
		end
	end)
	trackFrame.MouseEnter:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		setGlow(halo, 0.3, 0.15)
	end)
	trackFrame.MouseLeave:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		if not (self.Window and self.Window._drag) then
			setGlow(halo, 0.5, 0.25)
		end
	end)
	input.Focused:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(boxBorder, 0.15, { Color = Theme.Accent })
		input.Text = string.format("%." .. math.max(0, rounding) .. "f", api.Value)
	end)
	input.FocusLost:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(boxBorder, 0.25, { Color = Theme.ControlStroke })
		local typed = tonumber((string.gsub(input.Text, "[^%d%.%-]", "")))
		if typed then
			api:Set(typed)
		end
		input.Text = format(api.Value)
	end)

	local start = tonumber(info.Default) or min
	api.Value = quantize(start)
	api.Default = api.Value
	input.Text = format(api.Value)
	ready = true
	task.defer(layout, false)
	register(self, api, "Slider", explicit, display, info)
	return api
end

-- Dropdown -----------------------------------------------------------

function Card:AddDropdown(id, info, legacyDefault, legacyCallback)
	LPH_ATTRIBUTES(VM(NONE));
	local display, explicit
	if type(info) == "table" and (info.Values ~= nil or info.Text ~= nil or info.Multi ~= nil or info.Default ~= nil) then
		display, explicit = info.Text or tostring(id), id
	else
		display = tostring(id)
		info = { Text = display, Values = info or {}, Default = legacyDefault, Callback = legacyCallback }
	end
	local multi = info.Multi == true
	local row, element = makeRow(self, display, 43)
	local label = rowLabel(row, display)
	local api = { _element = element, _label = label, Multi = multi, AllowNull = info.AllowNull == true, Values = info.Values or {}, DisabledValues = {} }

	local pill = new("ImageButton", {
		Name = "Select",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -7, 0.5, 0),
		Size = UDim2.fromOffset(0, 26),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 0,
		Theme = { BackgroundColor3 = "Control" },
		Parent = row,
	})
	corner(pill, 12)
	local border = stroke(pill, "ControlStroke", 1, 0)
	new("UIPadding", { PaddingLeft = px(10), PaddingRight = px(10), Parent = pill })
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = px(10),
		Parent = pill,
	})
	local valueLabel = new("TextLabel", {
		Name = "Value",
		LayoutOrder = 1,
		Size = UDim2.fromOffset(0, 26),
		AutomaticSize = Enum.AutomaticSize.X,
		FontFace = Fonts.Label,
		TextSize = 15,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Text = "",
		Theme = { TextColor3 = "Text" },
		Parent = pill,
	})
	new("UISizeConstraint", { MinSize = Vector2.new(69, 0), MaxSize = Vector2.new(190, math.huge), Parent = valueLabel })
	local chevron = icon("chevron-down", 12, "TextTitle", { Name = "Chevron", LayoutOrder = 2, Parent = pill })
	label.Size = UDim2.new(1, -230, 1, 0)

	local function formatValue(value)
		LPH_ATTRIBUTES(VM(NONE));
		if type(info.FormatDisplayValue) == "function" then
			local ok, result = pcall(info.FormatDisplayValue, value)
			if ok and result ~= nil then
				return tostring(result)
			end
		end
		return tostring(value)
	end
	local function display_()
		LPH_ATTRIBUTES(VM(NONE));
		if multi then
			local picked = {}
			for _, option in ipairs(api.Values) do
				if api.Value[option] then
					table.insert(picked, formatValue(option))
				end
			end
			return #picked > 0 and table.concat(picked, ", ") or "None"
		end
		return api.Value ~= nil and formatValue(api.Value) or "None"
	end
	local function normalise(value)
		LPH_ATTRIBUTES(VM(NONE));
		if multi then
			local set = {}
			if type(value) == "table" then
				for k, v in pairs(value) do
					if type(k) == "number" then
						set[v] = true
					elseif v then
						set[k] = true
					end
				end
			end
			return set
		end
		if type(value) == "number" and api.Values[value] ~= nil and not table.find(api.Values, value) then
			return api.Values[value]
		end
		return value
	end

	function api:Get()
		LPH_ATTRIBUTES(VM(NONE));
		return self.Value
	end
	function api:Set(value, silent)
		LPH_ATTRIBUTES(VM(NONE));
		self.Value = normalise(value)
		valueLabel.Text = display_()
		changed(self, silent)
		return self
	end
	api.SetValue = api.Set
	function api:SetValues(values)
		LPH_ATTRIBUTES(VM(NONE));
		self.Values = values or {}
		if multi then
			local set = {}
			for k in pairs(self.Value or {}) do
				if table.find(self.Values, k) then
					set[k] = true
				end
			end
			self.Value = set
		elseif self.Value ~= nil and not table.find(self.Values, self.Value) then
			self.Value = self.AllowNull and nil or self.Values[1]
		end
		valueLabel.Text = display_()
		return self
	end
	function api:AddValues(values)
		LPH_ATTRIBUTES(VM(NONE));
		for _, v in ipairs(type(values) == "table" and values or { values }) do
			table.insert(self.Values, v)
		end
		return self:SetValues(self.Values)
	end
	function api:SetDisabledValues(values)
		LPH_ATTRIBUTES(VM(NONE));
		self.DisabledValues = values or {}
		return self
	end
	function api:GetActiveValues()
		LPH_ATTRIBUTES(VM(NONE));
		if not multi then
			return self.Value ~= nil and 1 or 0
		end
		local list = {}
		for _, option in ipairs(self.Values) do
			if self.Value[option] then
				table.insert(list, option)
			end
		end
		return list
	end
	function api:Display()
		LPH_ATTRIBUTES(VM(NONE));
		valueLabel.Text = display_()
	end

	local open = false
	pill.MouseButton1Click:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		if api.Disabled then
			return
		end
		if open then
			self.Window:_closePopup()
			return
		end
		local items = {}
		for _, option in ipairs(api.Values) do
			local text = tostring(option)
			if type(info.FormatListValue) == "function" then
				local ok, result = pcall(info.FormatListValue, option)
				if ok and result ~= nil then
					text = tostring(result)
				end
			end
			table.insert(items, {
				Text = text,
				Selected = multi and api.Value[option] == true or (not multi and api.Value == option),
				Disabled = table.find(api.DisabledValues, option) ~= nil,
				Callback = function(popup, index)
					LPH_ATTRIBUTES(VM(NONE));
					if multi then
						local set = cloneTable(api.Value)
						set[option] = not set[option] or nil
						api:Set(set)
						popup.Rows[index].SetSelected(set[option] == true)
						return true
					end
					if api.Value == option and api.AllowNull then
						api:Set(nil)
					else
						api:Set(option)
					end
				end,
			})
		end
		local width = math.max(pill.AbsoluteSize.X / self.Window._scale, 170)
		local popup = Popup.open(self.Window, pill, {
			Width = width,
			OnClose = function()
				LPH_ATTRIBUTES(VM(NONE));
				open = false
				tween(chevron, 0.25, { Rotation = 0 })
			end,
			Build = function(frame, popup)
				LPH_ATTRIBUTES(VM(NONE));
				return buildList(frame, popup, items, {
					Searchable = info.Searchable == true or #items > 12,
					MaxVisible = tonumber(info.MaxVisibleDropdownItems) or 8,
				})
			end,
		})
		if popup then
			open = true
			tween(chevron, 0.25, { Rotation = 180 })
		end
	end)
	pill.MouseEnter:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(border, 0.15, { Color = Theme.AccentDeep })
	end)
	pill.MouseLeave:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(border, 0.25, { Color = Theme.ControlStroke })
	end)

	local start = info.Default
	if not multi and start == nil and not api.AllowNull then
		start = api.Values[1]
	end
	api.Value = normalise(start)
	if not multi and api.Value ~= nil and not table.find(api.Values, api.Value) and not api.AllowNull then
		api.Value = api.Values[1]
	end
	api.Default = multi and cloneTable(api.Value) or api.Value
	valueLabel.Text = display_()
	register(self, api, "Dropdown", explicit, display, info)
	return api
end

function Card:AddMultiDropdown(id, info)
	LPH_ATTRIBUTES(VM(NONE));
	info = info or {}
	info.Multi = true
	return self:AddDropdown(id, info)
end

-- Input ---------------------------------------------------------------

function Card:AddInput(id, info, placeholder, legacyCallback)
	LPH_ATTRIBUTES(VM(NONE));
	local display, explicit
	if type(info) == "table" then
		display, explicit = info.Text or tostring(id), id
	else
		display = tostring(id)
		info = { Text = display, Default = info, Placeholder = placeholder, Callback = legacyCallback }
	end
	local row, element = makeRow(self, display, 43)
	local label = rowLabel(row, display, { Size = UDim2.new(1, -214, 1, 0) })
	local api = { _element = element, _label = label }
	local box = new("Frame", {
		Name = "Box",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -7, 0.5, 0),
		Size = UDim2.fromOffset(info.Width or 196, 26),
		BackgroundTransparency = 0,
		Theme = { BackgroundColor3 = "Control" },
		Parent = row,
	})
	corner(box, 12)
	local border = stroke(box, "ControlStroke", 1, 0)
	local textBox = new("TextBox", {
		Name = "Input",
		Position = UDim2.fromOffset(10, 0),
		Size = UDim2.new(1, -20, 1, 0),
		FontFace = Fonts.Label,
		TextSize = 15,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		ClearTextOnFocus = info.ClearTextOnFocus == true,
		PlaceholderText = tostring(info.Placeholder or info.PlaceholderText or ""),
		Text = "",
		Theme = { TextColor3 = "Text", PlaceholderColor3 = "Placeholder" },
		Parent = box,
	})
	api.Textbox = textBox

	local function clean(text)
		LPH_ATTRIBUTES(VM(NONE));
		text = tostring(text or "")
		if info.Numeric then
			text = string.gsub(text, "[^%d%.%-]", "")
		end
		if info.MaxLength and #text > info.MaxLength then
			text = string.sub(text, 1, info.MaxLength)
		end
		return text
	end
	function api:Get()
		LPH_ATTRIBUTES(VM(NONE));
		return self.Value
	end
	function api:Set(text, silent)
		LPH_ATTRIBUTES(VM(NONE));
		text = clean(text)
		if text == "" and info.AllowEmpty == false then
			text = tostring(info.EmptyReset or self.Value or "")
		end
		self.Value = text
		if textBox.Text ~= text then
			textBox.Text = text
		end
		changed(self, silent)
		return self
	end
	api.SetValue = api.Set

	local committing = false
	textBox:GetPropertyChangedSignal("Text"):Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		if committing then
			return
		end
		if info.Numeric or info.MaxLength then
			local cleaned = clean(textBox.Text)
			if cleaned ~= textBox.Text then
				textBox.Text = cleaned
				return
			end
		end
		if not info.Finished and textBox:IsFocused() and textBox.Text ~= api.Value then
			api:Set(textBox.Text)
		end
	end)
	textBox.Focused:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(border, 0.15, { Color = Theme.Accent })
	end)
	textBox.FocusLost:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(border, 0.25, { Color = Theme.ControlStroke })
		if api.Disabled then
			textBox.Text = api.Value
			return
		end
		if textBox.Text ~= api.Value then
			committing = true
			api:Set(textBox.Text)
			committing = false
		end
	end)

	api.Value = clean(info.Default or "")
	api.Default = api.Value
	textBox.Text = api.Value
	register(self, api, "Input", explicit, display, info)
	return api
end
Card.AddTextbox = Card.AddInput

-- Key picker / colour picker rows -----------------------------------------

function Card:AddKeyPicker(id, info)
	LPH_ATTRIBUTES(VM(NONE));
	info = info or {}
	local display = info.Text or tostring(id)
	local row, element = makeRow(self, display, 43)
	local label = rowLabel(row, display, { Size = UDim2.new(1, -200, 1, 0) })
	local picker = createKeyPicker(self, row, element, id, info, false)
	picker._label = label
	return picker
end

function Card:AddKeybind(id, default, callback, mode)
	LPH_ATTRIBUTES(VM(NONE));
	if type(default) == "table" then
		return self:AddKeyPicker(id, default)
	end
	return self:AddKeyPicker(id, { Text = tostring(id), Default = default, Callback = callback, Mode = mode })
end

function Card:AddColorPicker(id, info)
	LPH_ATTRIBUTES(VM(NONE));
	info = info or {}
	local display = info.Title or info.Text or tostring(id)
	local row, element = makeRow(self, display, 35)
	rowLabel(row, display, { Size = UDim2.new(1, -60, 1, 0) })
	return createColorPicker(self, row, element, id, info, false)
end

-- Label / divider / blank ----------------------------------------------------

function Card:AddLabel(text, wrap, idx)
	LPH_ATTRIBUTES(VM(NONE));
	if type(text) == "table" then
		wrap = text.DoesWrap or text.Wrap
		text = text.Text
	end
	text = tostring(text or "")
	local row, element = makeRow(self, text ~= "" and text or "Label", wrap and 24 or 32)
	element.SearchText = text
	row.BackgroundTransparency = 1
	local label = new("TextLabel", {
		Name = "Label",
		Position = UDim2.fromOffset(7, wrap and 6 or 0),
		Size = wrap and UDim2.new(1, -14, 0, 0) or UDim2.new(1, -14, 1, 0),
		AutomaticSize = wrap and Enum.AutomaticSize.Y or Enum.AutomaticSize.None,
		FontFace = wrap and Fonts.Body or Fonts.Label,
		TextSize = wrap and 14 or 15,
		TextWrapped = wrap == true,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = wrap and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center,
		TextTruncate = wrap and Enum.TextTruncate.None or Enum.TextTruncate.AtEnd,
		RichText = true,
		Text = text,
		Theme = { TextColor3 = wrap and "SubText" or "TextOff" },
		Parent = row,
	})
	if wrap then
		row.AutomaticSize = Enum.AutomaticSize.Y
		new("UIPadding", { PaddingBottom = px(6), Parent = row })
	end
	local api = setmetatable({ Container = row, Label = label, TextLabel = label, Text = text, _card = self, _element = element, Addons = {} }, {})
	function api:SetText(value)
		LPH_ATTRIBUTES(VM(NONE));
		self.Text = tostring(value)
		label.Text = self.Text
		element.SearchText = self.Text
		return self
	end
	function api:SetVisible(visible)
		LPH_ATTRIBUTES(VM(NONE));
		element:SetVisible(visible ~= false)
		return self
	end
	function api:AddColorPicker(colorId, colorInfo)
		LPH_ATTRIBUTES(VM(NONE));
		colorInfo = colorInfo or {}
		if colorInfo.Title == nil and colorInfo.Text == nil then
			colorInfo.Title = self.Text
		end
		label.Size = UDim2.new(1, -60, 1, 0)
		paint(label, { TextColor3 = "Text" })
		local picker = createColorPicker(self._card, row, element, colorId, colorInfo, false)
		table.insert(self.Addons, picker)
		return picker
	end
	function api:AddKeyPicker(keyId, keyInfo)
		LPH_ATTRIBUTES(VM(NONE));
		keyInfo = keyInfo or {}
		if keyInfo.Text == nil then
			keyInfo.Text = self.Text
		end
		row.Size = UDim2.new(1, 0, 0, 43)
		label.Size = UDim2.new(1, -200, 1, 0)
		label.FontFace = Fonts.Label
		label.TextSize = 16
		paint(label, { TextColor3 = "Text" })
		local picker = createKeyPicker(self._card, row, element, keyId, keyInfo, false)
		picker._label = label
		table.insert(self.Addons, picker)
		return picker
	end
	if idx then
		Library.Labels[idx] = api
	end
	return api
end

function Card:AddDivider(text)
	LPH_ATTRIBUTES(VM(NONE));
	local row, element = makeRow(self, "Divider", text and 26 or 12)
	element.SearchText = ""
	row.Divider.Visible = false
	local lineFrame = new("Frame", {
		Name = "Rule",
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 10, 0.5, 0),
		Size = UDim2.new(1, -20, 0, 1),
		BackgroundTransparency = 0.2,
		Theme = { BackgroundColor3 = "HeaderDivider" },
		Parent = row,
	})
	gradient(lineFrame, 0, nil, numberSeq(0, 1, 0.15, 0.2, 0.85, 0.2, 1, 1))
	if text then
		local tag = new("TextLabel", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(0, 18),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 0,
			FontFace = Fonts.CardSub,
			TextSize = 14,
			Text = tostring(text),
			Theme = { BackgroundColor3 = "BodyMid", TextColor3 = "SubText" },
			Parent = row,
		})
		new("UIPadding", { PaddingLeft = px(8), PaddingRight = px(8), Parent = tag })
	end
	return row
end

function Card:AddBlank(height, visible)
	LPH_ATTRIBUTES(VM(NONE));
	local row, element = makeRow(self, "Blank", tonumber(height) or 6)
	element.SearchText = ""
	row.Divider.Visible = false
	element:SetVisible(visible ~= false)
	return setmetatable({ Container = row, Visible = visible ~= false }, {
		__index = {
			SetVisible = function(api, value)
				LPH_ATTRIBUTES(VM(NONE));
				api.Visible = value ~= false
				element:SetVisible(api.Visible)
				return api
			end,
		},
	})
end

-- Buttons -------------------------------------------------------------------

function Card:AddButton(info, text, legacyCallback)
	LPH_ATTRIBUTES(VM(NONE));
	local label, fn, tooltip, doubleClick
	if type(info) == "table" then
		label, fn, tooltip, doubleClick = info.Text or "Button", info.Func or info.Callback, info.Tooltip, info.DoubleClick
	elseif type(text) == "function" and legacyCallback == nil then
		label, fn = tostring(info or "Button"), text
	else
		label, fn = tostring(text or info or "Button"), legacyCallback
	end
	local row, element = makeRow(self, label, 42)
	local line = new("Frame", { Name = "Buttons", Position = UDim2.fromOffset(7, 7), Size = UDim2.new(1, -14, 1, -14), BackgroundTransparency = 1, Parent = row })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder, Padding = px(6), Parent = line })
	local window = self.Window
	local card = self

	local function makeButton(text, callback, tip, confirm, order)
		LPH_ATTRIBUTES(VM(NONE));
		local button = new("TextButton", {
			Name = text,
			LayoutOrder = order,
			Size = UDim2.new(0, 10, 1, 0),
			BackgroundTransparency = 0,
			FontFace = Fonts.Label,
			TextSize = 15,
			Text = text,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Theme = { BackgroundColor3 = "Control", TextColor3 = "Text" },
			Parent = line,
		})
		new("UIFlexItem", { FlexMode = Enum.UIFlexMode.Fill, Parent = button })
		corner(button, 12)
		local border = stroke(button, "ControlStroke", 1, 0)
		local halo = glow(button, { Blur = 12, Transparency = 1 })
		local api = { Button = button, Container = row, Text = text, Func = callback, _card = card }
		local armedAt
		button.MouseEnter:Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			tween(border, 0.15, { Color = Theme.Accent })
			setGlow(halo, 0.6, 0.15)
		end)
		button.MouseLeave:Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			tween(border, 0.25, { Color = Theme.ControlStroke })
			tween(button, 0.25, { BackgroundColor3 = Theme.Control })
			setGlow(halo, 1, 0.25)
		end)
		button.MouseButton1Down:Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			if not api.Disabled then
				tween(button, 0.1, { BackgroundColor3 = Theme.AccentDeep })
			end
		end)
		button.MouseButton1Click:Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			tween(button, 0.3, { BackgroundColor3 = Theme.Control })
			if api.Disabled then
				return
			end
			if confirm then
				if not armedAt or os.clock() - armedAt > 2 then
					armedAt = os.clock()
					button.Text = "Click again to confirm"
					task.delay(2, function()
						LPH_ATTRIBUTES(VM(NONE));
						if armedAt and os.clock() - armedAt >= 1.95 then
							armedAt = nil
							button.Text = api.Text
						end
					end)
					return
				end
				armedAt = nil
				button.Text = api.Text
			end
			fire(api.Func)
		end)
		if tip and window then
			window:_attachTooltip(button, tip)
		end
		function api:OnClick(cb)
			LPH_ATTRIBUTES(VM(NONE));
			if type(cb) == "function" then
				button.MouseButton1Click:Connect(cb)
			end
			return self
		end
		function api:SetText(value)
			LPH_ATTRIBUTES(VM(NONE));
			self.Text = tostring(value)
			button.Text = self.Text
			return self
		end
		function api:SetDisabled(disabled)
			LPH_ATTRIBUTES(VM(NONE));
			self.Disabled = disabled == true
			button.TextTransparency = self.Disabled and 0.5 or 0
			return self
		end
		function api:SetVisible(visible)
			LPH_ATTRIBUTES(VM(NONE));
			button.Visible = visible ~= false
			return self
		end
		function api:AddButton(subInfo, subText, subCallback)
			LPH_ATTRIBUTES(VM(NONE));
			local t, f, tt, dc
			if type(subInfo) == "table" then
				t, f, tt, dc = subInfo.Text or "Button", subInfo.Func or subInfo.Callback, subInfo.Tooltip, subInfo.DoubleClick
			elseif type(subText) == "function" then
				t, f = tostring(subInfo), subText
			else
				t, f = tostring(subText or subInfo), subCallback
			end
			element.SearchText = element.SearchText .. " " .. t
			return makeButton(t, f, tt, dc, order + 1)
		end
		return api
	end
	local api = makeButton(label, fn, tooltip, doubleClick, 1)
	api._element = element
	table.insert(Library.Buttons, api)
	return api
end

-- Viewport ---------------------------------------------------------------

function Card:AddViewport(id, info)
	LPH_ATTRIBUTES(VM(NONE));
	info = info or {}
	local height = tonumber(info.Height) or 220
	local holder = new("Frame", {
		Name = tostring(id or "Viewport"),
		LayoutOrder = nextOrder(),
		Size = UDim2.new(1, 0, 0, height + 12),
		BackgroundTransparency = 1,
		Parent = self.Body,
	})
	local viewport = new("ViewportFrame", {
		Position = UDim2.fromOffset(8, 6),
		Size = UDim2.new(1, -16, 0, height),
		BackgroundTransparency = 0.08,
		Ambient = rgb(180, 160, 190),
		LightColor = WHITE,
		LightDirection = Vector3.new(-1, -1, -1),
		Theme = { BackgroundColor3 = "Window" },
		Parent = holder,
	})
	corner(viewport, 12)
	stroke(viewport, "Divider", 1, 0.2)
	local camera = info.Camera or makeInstance("Camera")
	camera.Parent = viewport
	viewport.CurrentCamera = camera
	local object = info.Object
	if object and info.Clone then
		local ok, clone = pcall(function()
			LPH_ATTRIBUTES(VM(NONE));
			return object:Clone()
		end)
		if ok then
			object = clone
		end
	end
	if object then
		object.Parent = viewport
	end
	local element = setmetatable({ Container = holder, SearchText = "", Card = self }, Element)
	table.insert(self.Elements, element)
	local api = { Type = "Viewport", Object = object, Camera = camera, Holder = holder, Container = viewport, Height = height, Visible = info.Visible ~= false, _card = self }
	holder.Visible = api.Visible
	function api:SetObject(newObject, clone)
		LPH_ATTRIBUTES(VM(NONE));
		if self.Object and self.Object.Parent == viewport then
			pcall(function()
				LPH_ATTRIBUTES(VM(NONE));
				self.Object:Destroy()
			end)
		end
		if newObject and clone then
			local ok, c = pcall(function()
				LPH_ATTRIBUTES(VM(NONE));
				return newObject:Clone()
			end)
			if ok then
				newObject = c
			end
		end
		self.Object = newObject
		if newObject then
			newObject.Parent = viewport
		end
		return self
	end
	function api:SetHeight(value)
		LPH_ATTRIBUTES(VM(NONE));
		self.Height = math.max(40, tonumber(value) or self.Height)
		holder.Size = UDim2.new(1, 0, 0, self.Height + 12)
		viewport.Size = UDim2.new(1, -16, 0, self.Height)
		return self
	end
	function api:SetVisible(value)
		LPH_ATTRIBUTES(VM(NONE));
		self.Visible = value ~= false
		element:SetVisible(self.Visible)
		return self
	end
	Library.Options[id] = api
	return api
end

-- Dependency boxes ------------------------------------------------------------

function Card:AddDependencyBox(name)
	LPH_ATTRIBUTES(VM(NONE));
	local host = new("Frame", {
		Name = tostring(name or "DependencyBox"),
		LayoutOrder = nextOrder(),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = self.Body,
	})
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = host })
	local proxy = setmetatable({
		Tab = self.Tab,
		Window = self.Window,
		Title = tostring(self.Title or "Card") .. "/" .. tostring(name or "Dependency"),
		Body = host,
		Container = host,
		Elements = self.Elements, -- searching treats the box's rows as the card's rows
		Dependencies = {},
		_host = self._host or self,
		_parentBox = self,
	}, Card)
	proxy.BodyList = host:FindFirstChildOfClass("UIListLayout")
	local element = setmetatable({ Container = host, SearchText = "", Card = self, IsBox = true }, Element)
	proxy._element = element
	local function evaluate()
		LPH_ATTRIBUTES(VM(NONE));
		local visible = true
		for _, dep in ipairs(proxy.Dependencies) do
			local option, expected = dep[1], dep[2]
			local current
			if option then
				if option.Type == "Dropdown" and option.Multi and type(expected) ~= "function" and type(expected) ~= "table" then
					current = option.Value and option.Value[expected] == true
					expected = true
				else
					current = option.Value
				end
			end
			if type(expected) == "function" then
				local ok, result = pcall(expected, current)
				visible = visible and ok and result == true
			else
				visible = visible and current == expected
			end
		end
		proxy.Visible = visible
		element.Hidden = not visible
		host.Visible = visible and not element._filtered
	end
	function proxy:RefreshDependencies()
		LPH_ATTRIBUTES(VM(NONE));
		evaluate()
		return self
	end
	function proxy:AddDependency(option, expected)
		LPH_ATTRIBUTES(VM(NONE));
		table.insert(self.Dependencies, { option, expected })
		if option and type(option.OnChanged) == "function" then
			option:OnChanged(evaluate)
		end
		evaluate()
		return self
	end
	function proxy:SetupDependencies(list)
		LPH_ATTRIBUTES(VM(NONE));
		self.Dependencies = {}
		for _, dep in ipairs(list or {}) do
			table.insert(self.Dependencies, { dep[1], dep[2] })
			if dep[1] and type(dep[1].OnChanged) == "function" then
				dep[1]:OnChanged(evaluate)
			end
		end
		evaluate()
		return self
	end
	function proxy:Resize()
		LPH_ATTRIBUTES(VM(NONE));
		if self._host and self._host.Resize then
			self._host:Resize()
		end
	end
	table.insert(self.Tab and self.Tab.DependencyGroupboxes or {}, proxy)
	return proxy
end
---------------------------------------------------------------------
-- Groupbox cards
---------------------------------------------------------------------

local Tab = {}
Tab.__index = Tab

local function paintCard(card)
	LPH_ATTRIBUTES(VM(NONE));
	local scale = card.Window._scale
	local height = card.Frame.AbsoluteSize.Y / scale
	local headerHeight = card.HeaderHeight
	if height <= 0 then
		return
	end
	local t = math.clamp(headerHeight / height, 0.02, 1)
	if t >= 0.95 then
		card._fill.Color = ColorSequence.new(Theme.HeaderTop, Theme.HeaderBottom)
		card._fill.Transparency = numberSeq(0, 0.16, 1, 0.24)
		return
	end
	card._fill.Color = colorSeq(
		0, Theme.HeaderTop,
		t, Theme.HeaderBottom,
		math.min(0.999, t + 0.002), Theme.BodyTop,
		t + (1 - t) * 0.45, Theme.BodyMid,
		1, Theme.BodyLow
	)
	card._fill.Transparency = numberSeq(0, 0.16, t, 0.24, math.min(0.999, t + 0.002), 0.16, 1, 0.2)
end

function Tab:AddCard(title, subtitle, side, iconName)
	LPH_ATTRIBUTES(VM(NONE));
	local window = self.Window
	title = tostring(title or "Groupbox")
	subtitle = tostring(subtitle or "")
	local rightSide = string.lower(tostring(side or "left")) == "right" or side == 2
	local card = setmetatable({
		Tab = self,
		Window = window,
		Title = title,
		Name = title,
		Subtitle = subtitle,
		Side = rightSide and 2 or 1,
		ColumnSide = rightSide and "right" or "left",
		Elements = {},
		Collapsed = false,
	}, Card)
	card._host = nil
	local headerHeight = subtitle ~= "" and 56 or 42
	card.HeaderHeight = headerHeight

	local frame = new("Frame", {
		Name = title,
		LayoutOrder = nextOrder(),
		Size = UDim2.new(1, 0, 0, headerHeight),
		BackgroundColor3 = WHITE,
		BackgroundTransparency = 0,
		Parent = rightSide and self.Right or self.Left,
	})
	corner(frame, CARD_RADIUS)
	card._fill = new("UIGradient", { Rotation = 90, Parent = frame })
	local border = stroke(frame, nil, 1, 0)
	border.Color = WHITE
	gradient(border, 90, { { 0, "CardStrokeTop" }, { 0.12, "CardStrokeMid" }, { 0.8, "CardStrokeMid" }, { 1, "CardStrokeLow" } })
	card._halo = glow(frame, { Blur = 20, Transparency = 0.8 })
	card.Frame, card.Outer = frame, frame

	local header = new("Frame", { Name = "Header", Size = UDim2.new(1, 0, 0, headerHeight), BackgroundTransparency = 1, Parent = frame })
	card.Header = header
	icon(iconName or iconForTitle(title, self.Icon), 17, "Accent", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 11, 0.5, 0),
		Parent = header,
	})
	local titleLabel = new("TextLabel", {
		Name = "Title",
		Position = UDim2.fromOffset(37, subtitle ~= "" and 8 or 0),
		Size = UDim2.new(1, -37 - 40, 0, subtitle ~= "" and 23 or headerHeight),
		FontFace = Fonts.CardTitle,
		TextSize = subtitle ~= "" and 23 or 21,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Text = title,
		Theme = { TextColor3 = "TextBright" },
		Parent = header,
	})
	card.TitleLabel = titleLabel
	if subtitle ~= "" then
		new("TextLabel", {
			Name = "Description",
			Position = UDim2.fromOffset(37, 31),
			Size = UDim2.new(1, -37 - 40, 0, 17),
			FontFace = Fonts.CardSub,
			TextSize = 17,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Text = subtitle,
			Theme = { TextColor3 = "SubText" },
			Parent = header,
		})
	end
	local menu = new("ImageButton", {
		Name = "Menu",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -8, 0.5, 0),
		Size = UDim2.fromOffset(22, 22),
		BackgroundColor3 = WHITE,
		Parent = header,
	})
	corner(menu, 7)
	local dots = icon("ellipsis", 16, "Text", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Parent = menu })
	menu.MouseEnter:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(menu, 0.15, { BackgroundTransparency = 0.9 })
		tween(dots, 0.15, { ImageColor3 = Theme.Accent })
	end)
	menu.MouseLeave:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(menu, 0.25, { BackgroundTransparency = 1 })
		tween(dots, 0.25, { ImageColor3 = Theme.Text })
	end)
	menu.MouseButton1Click:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		Popup.open(window, menu, {
			Width = 172,
			Build = function(f, popup)
				LPH_ATTRIBUTES(VM(NONE));
				return buildList(f, popup, {
					{ Text = card.Collapsed and "Expand" or "Collapse", Callback = function()
						LPH_ATTRIBUTES(VM(NONE));
						card:SetCollapsed(not card.Collapsed)
					end },
					{ Text = "Reset to defaults", Callback = function()
						LPH_ATTRIBUTES(VM(NONE));
						card:Reset()
					end },
				}, {})
			end,
		})
	end)

	local body = new("Frame", {
		Name = "Body",
		Position = UDim2.fromOffset(0, headerHeight),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Parent = frame,
	})
	local bodyList = new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = body })
	new("UIPadding", { PaddingBottom = px(4), Parent = body })
	card.Body, card.Container, card.BodyList = body, body, bodyList

	function card:Resize(animated)
		LPH_ATTRIBUTES(VM(NONE));
		if not self.Frame.Parent then
			return
		end
		local scale = window._scale
		local height = self.HeaderHeight
		if not self.Collapsed then
			height += round(self.BodyList.AbsoluteContentSize.Y / scale) + 6
		end
		local size = UDim2.new(1, 0, 0, height)
		if animated then
			self.Frame.ClipsDescendants = true
			tween(self.Frame, 0.3, { Size = size })
			task.delay(0.31, function()
				LPH_ATTRIBUTES(VM(NONE));
				if not self.Collapsed then
					self.Frame.ClipsDescendants = false
				end
			end)
		else
			self.Frame.Size = size
		end
		self.Tab:_RefreshCanvas()
	end
	function card:SetCollapsed(value)
		LPH_ATTRIBUTES(VM(NONE));
		self.Collapsed = value == true
		window:_closePopup()
		if self.Collapsed then
			self.Frame.ClipsDescendants = true
		end
		self:Resize(true)
		return self
	end
	function card:Reset()
		LPH_ATTRIBUTES(VM(NONE));
		for _, element in ipairs(self.Elements) do
			local option = element.ValueObject
			if option and option.Default ~= nil and option.Set and option.Type ~= "KeyPicker" then
				option:Set(option.Default)
			end
		end
	end

	bodyList:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		card:Resize()
	end)
	frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		paintCard(card)
	end)
	onTheme(function()
		LPH_ATTRIBUTES(VM(NONE));
		paintCard(card)
	end)
	frame.MouseEnter:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		setGlow(card._halo, 0.6, 0.25)
	end)
	frame.MouseLeave:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		setGlow(card._halo, 0.8, 0.4)
	end)

	table.insert(self.Cards, card)
	self:_UpdateCount()
	task.defer(function()
		LPH_ATTRIBUTES(VM(NONE));
		card:Resize()
	end)
	return card
end

---------------------------------------------------------------------
-- Tabboxes: a card with page pills along its top
---------------------------------------------------------------------

local Tabbox = {}
Tabbox.__index = Tabbox

function Tab:_AddTabbox(name, side)
	LPH_ATTRIBUTES(VM(NONE));
	local host = self:AddCard(name or "Tabs", "", side)
	local bar = new("Frame", {
		Name = "TabboxBar",
		LayoutOrder = -1,
		Size = UDim2.new(1, 0, 0, 38),
		BackgroundTransparency = 1,
		Parent = host.Body,
	})
	local strip = new("Frame", { Position = UDim2.fromOffset(8, 5), Size = UDim2.new(1, -16, 0, 28), BackgroundTransparency = 0, Theme = { BackgroundColor3 = "Control" }, Parent = bar })
	corner(strip, 14)
	stroke(strip, "ControlStroke", 1, 0)
	local buttons = new("Frame", { Position = UDim2.fromOffset(3, 3), Size = UDim2.new(1, -6, 1, -6), BackgroundTransparency = 1, Parent = strip })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder, Padding = px(3), Parent = buttons })
	local box = setmetatable({ Card = host, Window = self.Window, Tab = self, Buttons = buttons, Tabs = {}, Active = nil, Name = name }, Tabbox)
	self.Tabboxes[name or ""] = box
	return box
end

function Tab:AddLeftTabbox(name)
	LPH_ATTRIBUTES(VM(NONE));
	return self:_AddTabbox(name, "Left")
end

function Tab:AddRightTabbox(name)
	LPH_ATTRIBUTES(VM(NONE));
	return self:_AddTabbox(name, "Right")
end

function Tabbox:AddTab(name)
	LPH_ATTRIBUTES(VM(NONE));
	local host = self.Card
	local button = new("TextButton", {
		Name = name,
		LayoutOrder = #self.Tabs + 1,
		Size = UDim2.fromScale(0, 1),
		BackgroundTransparency = 1,
		FontFace = Fonts.Strong,
		TextSize = 14,
		Text = name,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Theme = { BackgroundColor3 = "AccentDeep", TextColor3 = "SubText" },
		Parent = self.Buttons,
	})
	new("UIFlexItem", { FlexMode = Enum.UIFlexMode.Fill, Parent = button })
	corner(button, 11)
	local page = new("Frame", {
		Name = name,
		LayoutOrder = nextOrder(),
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		Visible = false,
		Parent = host.Body,
	})
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = page })
	local proxy = setmetatable({
		Tab = host.Tab,
		Window = host.Window,
		Title = tostring(host.Title) .. "/" .. name,
		Name = name,
		Body = page,
		Container = page,
		Elements = host.Elements,
		_host = host,
		_tabbox = self,
	}, Card)
	proxy.BodyList = page:FindFirstChildOfClass("UIListLayout")
	local record = { Button = button, Page = page, Proxy = proxy }
	table.insert(self.Tabs, record)
	local box = self
	local function select()
		LPH_ATTRIBUTES(VM(NONE));
		if box.Active == record then
			return
		end
		if box.Active then
			box.Active.Page.Visible = false
			tween(box.Active.Button, 0.2, { BackgroundTransparency = 1, TextColor3 = Theme.SubText })
		end
		box.Active = record
		page.Visible = true
		tween(button, 0.2, { BackgroundTransparency = 0.15, TextColor3 = Theme.TextBright })
	end
	button.MouseButton1Click:Connect(select)
	function proxy:Show()
		LPH_ATTRIBUTES(VM(NONE));
		select()
	end
	if not self.Active then
		select()
	end
	return proxy
end

---------------------------------------------------------------------
-- Tabs and sub-tabs
---------------------------------------------------------------------

function Tab:AddGroupbox(info)
	LPH_ATTRIBUTES(VM(NONE));
	if type(info) == "string" then
		info = { Name = info, Side = 1 }
	end
	info = info or {}
	local name = info.Name or info.Text or ("Groupbox " .. tostring(#self.Cards + 1))
	local side = (info.Side == 2 or string.lower(tostring(info.Side)) == "right") and "Right" or "Left"
	local card = self:AddCard(name, info.Subtitle or info.Description or "", side, info.IconName or info.Icon)
	self.Groupboxes[name] = card
	return card
end

function Tab:AddLeftGroupbox(name, iconName)
	LPH_ATTRIBUTES(VM(NONE));
	return self:AddGroupbox({ Name = name, Side = 1, Icon = type(iconName) == "string" and iconName or nil })
end

function Tab:AddRightGroupbox(name, iconName)
	LPH_ATTRIBUTES(VM(NONE));
	return self:AddGroupbox({ Name = name, Side = 2, Icon = type(iconName) == "string" and iconName or nil })
end

function Tab:_UpdateCount()
	LPH_ATTRIBUTES(VM(NONE));
	local target = self.ParentTab or self
	local active = target.ActiveSubtab or target
	local n = #active.Cards
	if target.CountLabel then
		target.CountLabel.Text = n .. (n == 1 and " module" or " modules")
	end
end

function Tab:_RefreshCanvas()
	LPH_ATTRIBUTES(VM(NONE));
	if self._canvasQueued then
		return
	end
	self._canvasQueued = true
	task.defer(function()
		LPH_ATTRIBUTES(VM(NONE));
		self._canvasQueued = false
		if not self.Scroll or not self.Scroll.Parent then
			return
		end
		local scale = self.Window._scale
		local left = self.LeftList.AbsoluteContentSize.Y / scale
		local right = self.RightList.AbsoluteContentSize.Y / scale
		local height = math.max(left, right)
		self.Grid.Size = UDim2.new(1, -(GRID_LEFT + GRID_RIGHT), 0, height)
		self.Scroll.CanvasSize = UDim2.fromOffset(0, self.GridTop + height + 14)
		self.Window:_updateThumb()
	end)
end

function Tab:_ApplySearch(query)
	LPH_ATTRIBUTES(VM(NONE));
	local any = false
	for _, card in ipairs(self.Cards) do
		local titleHit = query == "" or string.find(string.lower(card.Title), query, 1, true) ~= nil
		local cardHit = titleHit
		for _, element in ipairs(card.Elements) do
			if not element.IsBox then
				local hit = titleHit or element:Matches(query)
				element._filtered = not hit
				element.Container.Visible = hit and not element.Hidden
				cardHit = cardHit or hit
			end
		end
		card.Frame.Visible = cardHit or card.Frame.Parent ~= (card.Side == 2 and self.Right or self.Left)
		any = any or cardHit
	end
	if self.Empty then
		self.Empty.Visible = query ~= "" and not any
	end
	self:_RefreshCanvas()
end

function Tab:_SetSelected(selected)
	LPH_ATTRIBUTES(VM(NONE));
	if self.ParentTab then
		local button = self.SubtabButton
		if button then
			tween(button, 0.2, { BackgroundTransparency = selected and 0.12 or 1 })
			tween(self.SubtabLabel, 0.2, { TextColor3 = selected and Theme.TextBright or Theme.SubText })
			tween(self.SubtabIcon, 0.2, { ImageColor3 = selected and Theme.TextBright or Theme.SubText })
		end
		return
	end
	if self.NavLabel then
		tween(self.NavLabel, 0.2, { TextColor3 = selected and Theme.TextBright or Theme.TextNav })
		tween(self.NavIcon, 0.2, { ImageColor3 = selected and Theme.TextBright or Theme.TextNav })
	end
end

function Tab:_SelectSubTab(sub)
	LPH_ATTRIBUTES(VM(NONE));
	if type(sub) == "string" then
		sub = self.SubtabByName and self.SubtabByName[sub]
	end
	if not sub or sub.ParentTab ~= self or self.ActiveSubtab == sub then
		return
	end
	local window = self.Window
	window:_closePopup()
	local previous = self.ActiveSubtab
	if previous then
		fadeFinish(previous.Page)
		previous.Page.Visible = false
		previous:_SetSelected(false)
	end
	self.ActiveSubtab = sub
	sub:_SetSelected(true)
	if previous and window.Visible then
		sub.Scroll.CanvasPosition = Vector2.new(0, 0)
		sub.Grid.Position = UDim2.fromOffset(GRID_LEFT, sub.GridTop + 14)
		tween(sub.Grid, 0.4, { Position = UDim2.fromOffset(GRID_LEFT, sub.GridTop) })
		fade(sub.Page, true, 0.2)
	else
		sub.Page.Visible = true
	end
	local pill = self.SubtabPill
	if pill and sub.SubtabButton then
		local bar = self.SubtabBar
		local scale = window._scale
		local x = (sub.SubtabButton.AbsolutePosition.X - bar.AbsolutePosition.X) / scale
		local w = sub.SubtabButton.AbsoluteSize.X / scale
		if previous and w > 0 then
			tween(pill, 0.36, { Position = UDim2.fromOffset(x, 0), Size = UDim2.new(0, w, 1, 0) }, Enum.EasingStyle.Back)
		else
			task.defer(function()
				LPH_ATTRIBUTES(VM(NONE));
				local s = window._scale
				pill.Position = UDim2.fromOffset((sub.SubtabButton.AbsolutePosition.X - bar.AbsolutePosition.X) / s, 0)
				pill.Size = UDim2.new(0, sub.SubtabButton.AbsoluteSize.X / s, 1, 0)
			end)
		end
	end
	self:_UpdateCount()
	if window.Search and window.Search.Text ~= "" then
		window.Search.Text = ""
	end
	window:_updateCrumb()
	sub:_RefreshCanvas()
	window:_updateThumb()
end

function Tab:SelectSubTab(sub)
	LPH_ATTRIBUTES(VM(NONE));
	self.Window:_SelectTab(self)
	self:_SelectSubTab(sub)
end

function Tab:Show()
	LPH_ATTRIBUTES(VM(NONE));
	if self.ParentTab then
		self.ParentTab:SelectSubTab(self)
	else
		self.Window:_SelectTab(self)
	end
end
Tab.Select = Tab.Show

function Tab:AddSubTab(name, iconName)
	LPH_ATTRIBUTES(VM(NONE));
	if self.SubtabByName and self.SubtabByName[name] then
		return self.SubtabByName[name]
	end
	local window = self.Window
	if not self.Subtabs then
		self.Subtabs, self.SubtabByName = {}, {}
		self.Scroll.Visible = false
		-- fixed header: title, module count and the sub-tab pills
		local fixed = new("Frame", { Name = "SubtabHeader", Size = UDim2.new(1, 0, 0, 98), BackgroundTransparency = 1, Parent = self.Page })
		self.Heading.Parent = fixed
		local barHolder = new("Frame", {
			Name = "SubtabStrip",
			Position = UDim2.fromOffset(GRID_LEFT, 54),
			Size = UDim2.new(1, -(GRID_LEFT + GRID_RIGHT), 0, 34),
			BackgroundTransparency = 0,
			Theme = { BackgroundColor3 = "Control" },
			Parent = fixed,
		})
		corner(barHolder, 17)
		stroke(barHolder, "ControlStroke", 1, 0)
		local bar = new("ScrollingFrame", {
			Name = "Subtabs",
			Position = UDim2.fromOffset(3, 3),
			Size = UDim2.new(1, -6, 1, -6),
			BackgroundTransparency = 1,
			CanvasSize = UDim2.new(),
			AutomaticCanvasSize = Enum.AutomaticSize.X,
			ScrollingDirection = Enum.ScrollingDirection.X,
			ScrollBarThickness = 0,
			Parent = barHolder,
		})
		local pill = new("Frame", { Name = "Selection", Size = UDim2.new(0, 0, 1, 0), BackgroundColor3 = WHITE, BackgroundTransparency = 0, ZIndex = 1, Parent = bar })
		corner(pill, 14)
		gradient(pill, 0, { "PillA", "PillB" }, numberSeq(0, 0.84, 0.55, 0.9, 1, 0.94))
		stroke(pill, "PillStroke", 1.5, 0)
		local row = new("Frame", { Name = "Buttons", Size = UDim2.fromScale(0, 1), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, ZIndex = 2, Parent = bar })
		new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder, Padding = px(4), Parent = row })
		self.SubtabBar, self.SubtabButtons, self.SubtabPill = bar, row, pill
		self.SubArea = new("Frame", { Name = "SubPages", Position = UDim2.fromOffset(0, 98), Size = UDim2.new(1, 0, 1, -98), BackgroundTransparency = 1, ClipsDescendants = true, Parent = self.Page })
	end
	local sub = window:_CreateTab(name, iconName, self)
	sub.ParentTab = self
	local button = new("ImageButton", {
		Name = name,
		LayoutOrder = #self.Subtabs + 1,
		Size = UDim2.fromScale(0, 1),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		ZIndex = 2,
		Parent = self.SubtabButtons,
	})
	new("UIPadding", { PaddingLeft = px(12), PaddingRight = px(14), Parent = button })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder, Padding = px(7), Parent = button })
	sub.SubtabIcon = icon(iconName or name, 15, "SubText", { LayoutOrder = 1, ZIndex = 2, Parent = button })
	sub.SubtabLabel = new("TextLabel", {
		LayoutOrder = 2,
		Size = UDim2.fromScale(0, 1),
		AutomaticSize = Enum.AutomaticSize.X,
		FontFace = Fonts.Strong,
		TextSize = 15,
		Text = name,
		ZIndex = 2,
		Theme = { TextColor3 = "SubText" },
		Parent = button,
	})
	sub.SubtabButton = button
	button.MouseButton1Click:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		self:SelectSubTab(sub)
	end)
	button.MouseEnter:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		if self.ActiveSubtab ~= sub then
			tween(sub.SubtabLabel, 0.15, { TextColor3 = Theme.Text })
		end
	end)
	button.MouseLeave:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		sub:_SetSelected(self.ActiveSubtab == sub)
	end)
	table.insert(self.Subtabs, sub)
	self.SubtabByName[name] = sub
	if not self.ActiveSubtab then
		self:_SelectSubTab(sub)
	end
	return sub
end
---------------------------------------------------------------------
-- Window
---------------------------------------------------------------------

local Window = {}
Window.__index = Window

function Window:_closePopup()
	LPH_ATTRIBUTES(VM(NONE));
	local popup = self._popup
	if popup then
		self._popup = nil
		popup:Close()
	end
end

function Window:_beginDrag(onMove, onEnd)
	LPH_ATTRIBUTES(VM(NONE));
	self._drag = { Move = onMove, End = onEnd }
end

function Window:_attachTooltip(target, text)
	LPH_ATTRIBUTES(VM(NONE));
	if type(text) ~= "string" or text == "" then
		return
	end
	local token = 0
	target.MouseEnter:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		token += 1
		local mine = token
		task.delay(0.45, function()
			LPH_ATTRIBUTES(VM(NONE));
			if mine ~= token or not self.Visible or not target.Parent then
				return
			end
			self:_showTooltip(text)
		end)
	end)
	target.MouseLeave:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		token += 1
		self:_hideTooltip()
	end)
end

function Window:_showTooltip(text)
	LPH_ATTRIBUTES(VM(NONE));
	local tip = self._tooltip
	self._tooltipLabel.Text = text
	tip.Visible = true
	self._tooltipOn = true
	tip.BackgroundTransparency = 1
	self._tooltipLabel.TextTransparency = 1
	tween(tip, 0.15, { BackgroundTransparency = 0.04 })
	tween(self._tooltipLabel, 0.15, { TextTransparency = 0 })
end

function Window:_hideTooltip()
	LPH_ATTRIBUTES(VM(NONE));
	self._tooltipOn = false
	if self._tooltip then
		self._tooltip.Visible = false
	end
end

function Window:_updateThumb()
	LPH_ATTRIBUTES(VM(NONE));
	local tab = self.ActiveTab
	if tab and tab.Subtabs then
		tab = tab.ActiveSubtab
	end
	local thumb = self._thumb
	if not tab or not tab.Scroll then
		thumb.Visible = false
		return
	end
	local scroll = tab.Scroll
	local view = scroll.AbsoluteWindowSize.Y
	local canvas = scroll.AbsoluteCanvasSize.Y
	if view <= 0 or canvas <= view + 1 then
		thumb.Visible = false
		return
	end
	local scale = self._scale
	local top = (scroll.AbsolutePosition.Y - self.Root.AbsolutePosition.Y) / scale + 2
	local trackLength = view / scale - 4
	local length = math.max(28, trackLength * view / canvas)
	local progress = math.clamp(scroll.CanvasPosition.Y / (canvas - view), 0, 1)
	thumb.Visible = true
	thumb.Size = UDim2.fromOffset(6, round(length))
	thumb.Position = UDim2.new(1, -9, 0, round(top + (trackLength - length) * progress))
end

function Window:_updateCrumb()
	LPH_ATTRIBUTES(VM(NONE));
	local tab = self.ActiveTab
	if not tab then
		return
	end
	self._crumb.Text = tab.Name
end

function Window:_CreateTab(name, iconName, parentTab)
	LPH_ATTRIBUTES(VM(NONE));
	local tab = setmetatable({
		Window = self,
		Name = name,
		Icon = iconName or name,
		Cards = {},
		Groupboxes = {},
		Tabboxes = {},
		DependencyGroupboxes = {},
	}, Tab)

	local page = new("Frame", {
		Name = name,
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = parentTab and parentTab.SubArea or self.Pages,
	})
	tab.Page = page
	local scroll = new("ScrollingFrame", {
		Name = "Scroll",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		CanvasSize = UDim2.new(),
		ScrollBarThickness = 0,
		ScrollBarImageTransparency = 1,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ElasticBehavior = Enum.ElasticBehavior.Never,
		Parent = page,
	})
	tab.Scroll = scroll
	tab.Sides = { scroll, scroll }

	local gridTop = 12
	if not parentTab then
		local heading = new("Frame", { Name = "Heading", Position = UDim2.fromOffset(14, 17), Size = UDim2.new(1, -40, 0, 27), BackgroundTransparency = 1, Parent = scroll })
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Bottom,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = px(10),
			Parent = heading,
		})
		new("TextLabel", {
			Name = "Title",
			LayoutOrder = 1,
			Size = UDim2.fromOffset(0, 27),
			AutomaticSize = Enum.AutomaticSize.X,
			FontFace = Fonts.PageTitle,
			TextSize = 27,
			Text = name,
			Theme = { TextColor3 = "TextTitle" },
			Parent = heading,
		})
		tab.CountLabel = new("TextLabel", {
			Name = "Count",
			LayoutOrder = 2,
			Size = UDim2.fromOffset(0, 18),
			AutomaticSize = Enum.AutomaticSize.X,
			FontFace = Fonts.Body,
			TextSize = 16,
			TextYAlignment = Enum.TextYAlignment.Top,
			Text = "0 modules",
			Theme = { TextColor3 = "SubText" },
			Parent = heading,
		})
		tab.Heading, tab.Header = heading, heading
		gridTop = 53
	end
	tab.GridTop = gridTop
	local grid = new("Frame", { Name = "Grid", Position = UDim2.fromOffset(GRID_LEFT, gridTop), Size = UDim2.new(1, -(GRID_LEFT + GRID_RIGHT), 0, 0), BackgroundTransparency = 1, Parent = scroll })
	tab.Grid = grid
	local function column(colName, x)
		LPH_ATTRIBUTES(VM(NONE));
		local col = new("Frame", {
			Name = colName,
			Position = UDim2.new(x, x > 0 and COLUMN_GAP / 2 or 0, 0, 0),
			Size = UDim2.new(0.5, -COLUMN_GAP / 2, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
			Parent = grid,
		})
		local list = new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = px(CARD_GAP), Parent = col })
		list:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			tab:_RefreshCanvas()
		end)
		return col, list
	end
	tab.Left, tab.LeftList = column("Left", 0)
	tab.Right, tab.RightList = column("Right", 0.5)
	tab.Empty = new("TextLabel", {
		Name = "Empty",
		Position = UDim2.fromOffset(14, gridTop + 8),
		Size = UDim2.new(1, -40, 0, 22),
		FontFace = Fonts.CardSub,
		TextSize = 19,
		TextXAlignment = Enum.TextXAlignment.Left,
		Text = "Nothing matches your search.",
		Visible = false,
		Theme = { TextColor3 = "SubText" },
		Parent = scroll,
	})
	scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		self:_closePopup()
		self:_updateThumb()
	end)
	scroll:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		self:_updateThumb()
	end)
	scroll:GetPropertyChangedSignal("AbsoluteCanvasSize"):Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		self:_updateThumb()
	end)

	table.insert(self.Tabs, tab)
	Library.Tabs[name] = tab
	return tab
end

function Window:AddTab(name, iconName)
	LPH_ATTRIBUTES(VM(NONE));
	if type(name) == "table" then
		iconName = name.Icon
		name = name.Name or name.Title
	end
	name = tostring(name or "Tab")
	local tab = self:_CreateTab(name, iconName)
	local isSettings = name == "Settings" or name == "UI Settings"

	if isSettings and not self._settingsDivider then
		self._settingsDivider = new("Frame", {
			Name = "Divider",
			LayoutOrder = 999,
			Size = UDim2.new(1, -28, 0, 9),
			BackgroundTransparency = 1,
			Parent = self.Nav,
		})
		new("Frame", { Position = UDim2.new(0, 15, 0.5, 0), Size = UDim2.new(1, -15, 0, 1), BackgroundTransparency = 0.1, Theme = { BackgroundColor3 = "LineDim" }, Parent = self._settingsDivider })
	end
	self._navCount = (self._navCount or 0) + 1
	local button = new("TextButton", {
		Name = name,
		LayoutOrder = isSettings and 1000 + self._navCount or self._navCount,
		Size = UDim2.new(1, 0, 0, NAV_HEIGHT),
		ZIndex = 2,
		Parent = self.Nav,
	})
	local glyph = icon(iconName or name, 21, "TextNav", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 14, 0.5, 0), ZIndex = 2, Parent = button })
	local label = new("TextLabel", {
		Name = "Label",
		Position = UDim2.fromOffset(45, 0),
		Size = UDim2.new(1, -70, 1, 0),
		FontFace = Fonts.Nav,
		TextSize = 21,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
		Text = name,
		ZIndex = 2,
		Theme = { TextColor3 = "TextNav" },
		Parent = button,
	})
	tab.NavButton, tab.NavIcon, tab.NavLabel = button, glyph, label
	button.MouseEnter:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		if self.ActiveTab ~= tab then
			tween(label, 0.15, { TextColor3 = Theme.Text, Position = UDim2.fromOffset(48, 0) })
			tween(glyph, 0.15, { ImageColor3 = Theme.Text })
		end
	end)
	button.MouseLeave:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		tween(label, 0.25, { Position = UDim2.fromOffset(45, 0) })
		if self.ActiveTab ~= tab then
			tween(label, 0.25, { TextColor3 = Theme.TextNav })
			tween(glyph, 0.25, { ImageColor3 = Theme.TextNav })
		end
	end)
	button.MouseButton1Click:Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		self:_SelectTab(tab)
	end)
	if not self.ActiveTab then
		self:_SelectTab(tab, true)
	end
	return tab
end

function Window:_SelectTab(tab, instant)
	LPH_ATTRIBUTES(VM(NONE));
	if tab.ParentTab then
		tab.ParentTab:SelectSubTab(tab)
		return
	end
	local previous = self.ActiveTab
	if previous == tab then
		return
	end
	self:_closePopup()
	self.ActiveTab = tab
	if previous then
		fadeFinish(previous.Page)
		previous.Page.Visible = false
		previous:_SetSelected(false)
	end
	tab:_SetSelected(true)
	if instant or not self.Visible then
		tab.Page.Visible = true
		task.defer(function()
			LPH_ATTRIBUTES(VM(NONE));
			self:_movePill(true)
		end)
	else
		self:_movePill(false)
		local inner = tab.Subtabs and tab.ActiveSubtab or tab
		inner.Scroll.CanvasPosition = Vector2.new(0, 0)
		inner.Grid.Position = UDim2.fromOffset(GRID_LEFT, inner.GridTop + 16)
		tween(inner.Grid, 0.4, { Position = UDim2.fromOffset(GRID_LEFT, inner.GridTop) })
		fade(tab.Page, true, 0.22)
	end
	if self.Search.Text ~= "" then
		self.Search.Text = ""
	end
	tab:_UpdateCount()
	self:_updateCrumb()
	self:_updateThumb()
end

-- Visibility ------------------------------------------------------------------

function Window:_loop(handle, peak, period)
	LPH_ATTRIBUTES(VM(NONE));
	if not handle or not handle.Instance then
		return
	end
	local entry = { Handle = handle, Peak = peak, Period = period }
	table.insert(self._loops, entry)
	self:_startLoop(entry)
end

function Window:_startLoop(entry)
	LPH_ATTRIBUTES(VM(NONE));
	if entry.Tween then
		entry.Tween:Cancel()
	end
	local handle = entry.Handle
	handle.Instance[handle.Property] = effective(handle.Base, handle.Black)
	entry.Tween = TweenService:Create(handle.Instance, TweenInfo.new(entry.Period, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
		[handle.Property] = effective(entry.Peak, handle.Black),
	})
	entry.Tween:Play()
end

function Window:_restartLoops()
	LPH_ATTRIBUTES(VM(NONE));
	for _, entry in ipairs(self._loops) do
		self:_startLoop(entry)
	end
end

function Window:SetVisible(visible)
	LPH_ATTRIBUTES(VM(NONE));
	visible = visible == true
	if self.Visible == visible and self._shown ~= nil then
		return
	end
	self.Visible = visible
	self._shown = visible
	Library.Toggled = visible
	self:_closePopup()
	self:_hideTooltip()
	local root, scaler = self.Root, self._scaler
	if visible then
		self.Gui.Enabled = true
		if self._blur and self.BlurEnabled then
			self._blur:SetEnabled(true)
		end
		scaler.Scale = self._scale * 0.955
		tween(scaler, 0.38, { Scale = self._scale }, Enum.EasingStyle.Back)
		for _, entry in ipairs(self._loops) do
			if entry.Tween then
				entry.Tween:Cancel()
			end
		end
		fade(root, true, 0.24, function()
			LPH_ATTRIBUTES(VM(NONE));
			self:_restartLoops()
		end)
		self:_applyInputState(true)
	else
		self:_applyInputState(false)
		tween(scaler, 0.2, { Scale = self._scale * 0.97 }, Enum.EasingStyle.Quad)
		fade(root, false, 0.18, function()
			LPH_ATTRIBUTES(VM(NONE));
			if not self.Visible then
				self.Gui.Enabled = false
				if self._blur then
					self._blur:SetEnabled(false)
				end
			end
		end)
	end
end

function Window:Toggle()
	LPH_ATTRIBUTES(VM(NONE));
	self:SetVisible(not self.Visible)
end

function Window:SetBlurEnabled(enabled)
	LPH_ATTRIBUTES(VM(NONE));
	self.BlurEnabled = enabled ~= false
	if self._blur then
		self._blur:SetEnabled(self.BlurEnabled and self.Visible)
	end
end

function Window:SetFlowersVisible(visible)
	LPH_ATTRIBUTES(VM(NONE));
	self.DecorationsEnabled = visible ~= false
	for _, item in ipairs(self._decor) do
		item.Visible = self.DecorationsEnabled
	end
end

function Window:SetGlowStrength(value)
	LPH_ATTRIBUTES(VM(NONE));
	Library.GlowStrength = math.clamp(tonumber(value) or 0.2, 0, 1)
	self.GlowStrength = Library.GlowStrength
	refreshGlows()
	if self.Visible then
		self:_restartLoops()
	end
end

function Window:SetBackgroundImage(value)
	LPH_ATTRIBUTES(VM(NONE));
	value = tostring(value or "")
	local id = value
	if string.match(value, "^%d+$") then
		id = "rbxassetid://" .. value
	end
	if value == "" then
		self._backdrop.Image = Assets.background
		self._blossoms.Visible = self.DecorationsEnabled
	else
		self._backdrop.Image = id
	end
	self.BackgroundImage = value
end

function Window:SetScale(scale)
	LPH_ATTRIBUTES(VM(NONE));
	self._userScale = tonumber(scale) or 1
	self:_fit()
end

function Window:SetSize(size)
	LPH_ATTRIBUTES(VM(NONE));
	if typeof(size) == "UDim2" then
		size = Vector2.new(size.X.Offset, size.Y.Offset)
	end
	if typeof(size) == "Vector2" then
		self._size = size
		self.Root.Size = UDim2.fromOffset(size.X, size.Y)
		self:_fit()
	end
end

function Window:_fit()
	LPH_ATTRIBUTES(VM(NONE));
	local camera = workspace.CurrentCamera
	local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
	local size = self._size
	local fit = math.min((viewport.X - 16) / size.X, (viewport.Y - 16) / size.Y)
	local scale = math.clamp(math.min(self._userScale, fit), 0.35, 3)
	self._scale = scale
	self._scaler.Scale = scale
end

function Window:SetToggleKeybind(value)
	LPH_ATTRIBUTES(VM(NONE));
	if typeof(value) == "EnumItem" then
		self.MenuKeybind = value
	end
end

function Window:SetKeybindListVisible(value)
	LPH_ATTRIBUTES(VM(NONE));
	if Library.KeybindFrame then
		Library.KeybindFrame.Visible = value == true
	end
end

function Window:SetWatermarkVisible(value)
	LPH_ATTRIBUTES(VM(NONE));
	self.Watermark.Visible = value == true
end

function Window:SetWatermark(text)
	LPH_ATTRIBUTES(VM(NONE));
	self.WatermarkLabel.Text = tostring(text or "")
end

function Window:SetNotifySide(side)
	LPH_ATTRIBUTES(VM(NONE));
	side = tostring(side or "Right")
	Library.NotifySide = side
	local area = self.NotificationArea
	local left = string.lower(side) == "left"
	area.AnchorPoint = Vector2.new(left and 0 or 1, 1)
	area.Position = left and UDim2.new(0, 18, 1, -18) or UDim2.new(1, -18, 1, -18)
end

function Window:GetOption(id)
	LPH_ATTRIBUTES(VM(NONE));
	return Library.Options[id] or Library.Toggles[id]
end

-- Keybind list -------------------------------------------------------------------

function Window:_refreshKeybinds()
	LPH_ATTRIBUTES(VM(NONE));
	if self._kbQueued then
		return
	end
	self._kbQueued = true
	task.defer(function()
		LPH_ATTRIBUTES(VM(NONE));
		self._kbQueued = false
		if not self.KeybindListBody or not self.KeybindListBody.Parent then
			return
		end
		local always = Library.KeybindMenuMode == "Always"
		local used = {}
		local order = 0
		for _, bind in ipairs(self.Keybinds) do
			local key = bind:Get()
			local show = bind.ShowInList and key ~= KEY_NONE and (always or bind:IsActive())
			if show then
				order += 1
				local entry = self._kbRows[bind]
				if not entry then
					local row = new("Frame", { Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1, Parent = self.KeybindListBody })
					local nameLabel = new("TextLabel", {
						Name = "Name",
						Size = UDim2.new(1, -96, 1, 0),
						FontFace = Fonts.Body,
						TextSize = 14,
						TextXAlignment = Enum.TextXAlignment.Left,
						TextTruncate = Enum.TextTruncate.AtEnd,
						Theme = { TextColor3 = "Text" },
						Parent = row,
					})
					local keyText = new("TextLabel", {
						Name = "Key",
						AnchorPoint = Vector2.new(1, 0),
						Position = UDim2.fromScale(1, 0),
						Size = UDim2.new(0, 92, 1, 0),
						FontFace = Fonts.Strong,
						TextSize = 13,
						TextXAlignment = Enum.TextXAlignment.Right,
						Parent = row,
					})
					entry = { Frame = row, Name = nameLabel, Key = keyText }
					self._kbRows[bind] = entry
				end
				entry.Frame.LayoutOrder = order
				entry.Name.Text = bind.DisplayName or bind.Id or "Keybind"
				entry.Key.Text = "[" .. keyLabel(key) .. "]  " .. bind:GetMode()
				entry.Key.TextColor3 = bind:IsActive() and Theme.Accent or Theme.SubText
				entry.Frame.Visible = true
				used[bind] = true
			end
		end
		for bind, entry in pairs(self._kbRows) do
			if not used[bind] then
				entry.Frame.Visible = false
			end
		end
		self._kbEmpty.Visible = order == 0
	end)
end

-- Notifications ---------------------------------------------------------------------

function Window:Notify(message, duration, kind)
	LPH_ATTRIBUTES(VM(NONE));
	if not self.NotificationsEnabled or not self.NotificationArea or not self.NotificationArea.Parent then
		return
	end
	local title, body = nil, tostring(message)
	if type(message) == "table" then
		title = message.Title
		body = tostring(message.Description or message.Text or message.Content or "")
		duration = message.Time or message.Duration or duration
		kind = message.Type or kind
	end
	duration = tonumber(duration) or 3.2
	self._toasts = (self._toasts or 0) + 1
	local toast = new("Frame", {
		Name = "Toast",
		LayoutOrder = self._toasts,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = WHITE,
		BackgroundTransparency = 0,
		Visible = false,
		Parent = self.NotificationArea,
	})
	corner(toast, 13)
	gradient(toast, 90, { "HeaderTop", "BodyMid" }, numberSeq(0, 0.04, 1, 0.04))
	local border = stroke(toast, nil, 1, 0)
	border.Color = WHITE
	gradient(border, 90, { "CardStrokeTop", "CardStrokeLow" })
	glow(toast, { Blur = 22, Transparency = 0.7 })
	local accentKey = kind == "Error" and "Risk" or (kind == "Success" and "Green" or "Accent")
	icon(kind == "Error" and "x" or (kind == "Success" and "check" or "sparkles"), 16, accentKey, { Name = "Badge", Position = UDim2.fromOffset(13, title and 13 or 11), Parent = toast })
	local column = new("Frame", { Name = "Text", Position = UDim2.fromOffset(38, 0), Size = UDim2.new(1, -52, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Parent = toast })
	new("UIPadding", { PaddingTop = px(title and 9 or 10), PaddingBottom = px(title and 11 or 10), Parent = column })
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = px(2), Parent = column })
	if title and tostring(title) ~= "" then
		new("TextLabel", {
			LayoutOrder = 1,
			Size = UDim2.new(1, 0, 0, 22),
			FontFace = Fonts.CardTitle,
			TextSize = 20,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Text = tostring(title),
			Theme = { TextColor3 = "TextBright" },
			Parent = column,
		})
	end
	if body ~= "" then
		new("TextLabel", {
			LayoutOrder = 2,
			Size = UDim2.new(1, 0, 0, 16),
			AutomaticSize = Enum.AutomaticSize.Y,
			FontFace = Fonts.Body,
			TextSize = 15,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Top,
			TextWrapped = true,
			RichText = true,
			Text = body,
			Theme = { TextColor3 = title and "SubText" or "Text" },
			Parent = column,
		})
	end
	fade(toast, true, 0.25)
	local api = { Frame = toast }
	function api:Destroy()
		LPH_ATTRIBUTES(VM(NONE));
		if toast.Parent then
			fade(toast, false, 0.3, function()
				LPH_ATTRIBUTES(VM(NONE));
				toast:Destroy()
			end)
		end
	end
	api.Hide = api.Destroy
	function api:SetText(text)
		LPH_ATTRIBUTES(VM(NONE));
		local labels = column:GetChildren()
		for _, child in ipairs(labels) do
			if child:IsA("TextLabel") and child.LayoutOrder == 2 then
				child.Text = tostring(text)
			end
		end
	end
	task.delay(duration, function()
		LPH_ATTRIBUTES(VM(NONE));
		api:Destroy()
	end)
	return api
end

-- Dialogs ---------------------------------------------------------------------------

function Window:AddDialog(id, info)
	LPH_ATTRIBUTES(VM(NONE));
	info = info or {}
	local window = self
	local overlay = new("TextButton", {
		Name = "Dialog_" .. tostring(id),
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = BLACK,
		BackgroundTransparency = 0.45,
		ZIndex = 60,
		Parent = self.Root,
	})
	corner(overlay, 10)
	local frame = new("Frame", {
		Name = "Dialog",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(480, 160),
		BackgroundColor3 = WHITE,
		BackgroundTransparency = 0,
		Active = true,
		ZIndex = 61,
		Parent = overlay,
	})
	corner(frame, CARD_RADIUS)
	gradient(frame, 90, { { 0, "HeaderTop" }, { 0.25, "BodyTop" }, { 0.7, "BodyMid" }, { 1, "BodyLow" } }, numberSeq(0, 0.02, 1, 0.02))
	local border = stroke(frame, nil, 1, 0)
	border.Color = WHITE
	gradient(border, 90, { "CardStrokeTop", "CardStrokeLow" })
	glow(frame, { Blur = 30, Transparency = 0.7 })
	new("TextLabel", {
		Position = UDim2.fromOffset(18, 12),
		Size = UDim2.new(1, -36, 0, 28),
		FontFace = Fonts.CardTitle,
		TextSize = 25,
		TextXAlignment = Enum.TextXAlignment.Left,
		Text = tostring(info.Title or "Dialog"),
		ZIndex = 62,
		Theme = { TextColor3 = "TextBright" },
		Parent = frame,
	})
	local desc = new("TextLabel", {
		Position = UDim2.fromOffset(18, 42),
		Size = UDim2.new(1, -36, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		FontFace = Fonts.CardSub,
		TextSize = 16,
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		Text = tostring(info.Description or ""),
		ZIndex = 62,
		Theme = { TextColor3 = "SubText" },
		Parent = frame,
	})
	local body = new("Frame", { Name = "Body", Position = UDim2.fromOffset(6, 70), Size = UDim2.new(1, -12, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, ZIndex = 62, Parent = frame })
	local bodyList = new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = body })
	local footer = new("Frame", { Name = "Footer", Size = UDim2.new(1, -36, 0, 32), BackgroundTransparency = 1, ZIndex = 62, Parent = frame })
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Right, SortOrder = Enum.SortOrder.LayoutOrder, Padding = px(8), Parent = footer })

	local dialog = setmetatable({
		Window = self,
		Tab = nil,
		Title = tostring(info.Title or "Dialog"),
		Body = body,
		Container = body,
		BodyList = bodyList,
		Elements = {},
		Overlay = overlay,
		Frame = frame,
		Footer = footer,
		FooterButtons = {},
	}, Card)
	function dialog:Resize()
		LPH_ATTRIBUTES(VM(NONE));
		task.defer(function()
			LPH_ATTRIBUTES(VM(NONE));
			if not overlay.Parent then
				return
			end
			local scale = window._scale
			local descH = math.max(0, desc.AbsoluteSize.Y / scale)
			local bodyH = bodyList.AbsoluteContentSize.Y / scale
			local top = 42 + descH + 12
			body.Position = UDim2.fromOffset(6, top)
			footer.Position = UDim2.fromOffset(18, top + bodyH + 10)
			frame.Size = UDim2.fromOffset(480, top + bodyH + 10 + 32 + 16)
		end)
	end
	function dialog:Dismiss()
		LPH_ATTRIBUTES(VM(NONE));
		if overlay.Parent then
			fade(overlay, false, 0.15, function()
				LPH_ATTRIBUTES(VM(NONE));
				overlay:Destroy()
			end)
		end
		Library.Dialogues[id] = nil
	end
	dialog.Close = dialog.Dismiss
	function dialog:RemoveFooterButton(buttonId)
		LPH_ATTRIBUTES(VM(NONE));
		local old = self.FooterButtons[buttonId]
		if old and old.Container then
			old.Container:Destroy()
		end
		self.FooterButtons[buttonId] = nil
	end
	function dialog:AddFooterButton(buttonId, buttonInfo)
		LPH_ATTRIBUTES(VM(NONE));
		buttonInfo = buttonInfo or {}
		self:RemoveFooterButton(buttonId)
		local variant = buttonInfo.Variant or "Secondary"
		local destructive = variant == "Destructive"
		local primary = variant == "Primary"
		local ghost = variant == "Ghost"
		local btn = new("TextButton", {
			Name = tostring(buttonId),
			LayoutOrder = tonumber(buttonInfo.Order) or 0,
			Size = UDim2.fromOffset(0, 30),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = ghost and 1 or 0,
			FontFace = Fonts.Label,
			TextSize = 15,
			Text = tostring(buttonInfo.Title or buttonId),
			ZIndex = 63,
			Theme = { BackgroundColor3 = primary and "AccentDeep" or "Control", TextColor3 = destructive and "Risk" or "Text" },
			Parent = footer,
		})
		new("UIPadding", { PaddingLeft = px(16), PaddingRight = px(16), Parent = btn })
		corner(btn, 12)
		stroke(btn, primary and "Accent" or (destructive and "Risk" or "ControlStroke"), 1, ghost and 0.4 or 0)
		btn.MouseButton1Click:Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			fire(buttonInfo.Callback, self)
			if info.AutoDismiss ~= false and buttonInfo.AutoDismiss ~= false then
				self:Dismiss()
			end
		end)
		local wrap = { Container = btn }
		self.FooterButtons[buttonId] = wrap
		return wrap
	end
	bodyList:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
		LPH_ATTRIBUTES(VM(NONE));
		dialog:Resize()
	end)
	if info.OutsideClickDismiss ~= false then
		overlay.MouseButton1Click:Connect(function()
			LPH_ATTRIBUTES(VM(NONE));
			dialog:Dismiss()
		end)
	end
	for buttonId, buttonInfo in pairs(info.FooterButtons or {}) do
		dialog:AddFooterButton(buttonId, buttonInfo)
	end
	dialog:Resize()
	overlay.Visible = false
	fade(overlay, true, 0.2)
	if Library.Dialogues[id] and Library.Dialogues[id] ~= dialog then
		pcall(function()
			LPH_ATTRIBUTES(VM(NONE));
			Library.Dialogues[id]:Dismiss()
		end)
	end
	Library.Dialogues[id] = dialog
	return dialog
end

-- Teardown ----------------------------------------------------------------------

function Window:Destroy()
	LPH_ATTRIBUTES(VM(NONE));
	self._alive = false
	self:_closePopup()
	if self._blur then
		self._blur:Destroy()
	end
	pcall(function()
		LPH_ATTRIBUTES(VM(NONE));
		ContextActionService:UnbindAction(self._inputAction)
	end)
	pcall(function()
		LPH_ATTRIBUTES(VM(NONE));
		UserInputService.MouseIconEnabled = true
	end)
	for _, gui in ipairs({ self.Gui, self.NotificationGui, self.MobileToggleGui }) do
		if gui then
			gui:Destroy()
		end
	end
end
---------------------------------------------------------------------
-- Decorative animation
---------------------------------------------------------------------

local function spawnPetals(window, layer, count)
	LPH_ATTRIBUTES(VM(NONE));
	if Assets.petal == "" then
		return
	end
	for i = 1, count do
		task.spawn(function()
			LPH_ATTRIBUTES(VM(NONE));
			local rng = Random.new(os.clock() * 1000 + i * 977)
			task.wait(rng:NextNumber(0, 9))
			while window._alive do
				if not (window.Visible and window.DecorationsEnabled) then
					task.wait(1)
					continue
				end
				local fromLeft = rng:NextNumber() < 0.45
				local startX = fromLeft and rng:NextNumber(0.01, 0.1) or rng:NextNumber(0.86, 0.99)
				local startY = rng:NextNumber(40, 150)
				local fall = rng:NextNumber(260, 430)
				local drift = rng:NextNumber(-90, 90) + (fromLeft and 60 or -60)
				local life = rng:NextNumber(7, 12)
				local size = rng:NextInteger(1, 2) * 7
				local holder = new("Frame", { Position = UDim2.new(startX, 0, 0, startY), Size = UDim2.fromOffset(1, 1), BackgroundTransparency = 1, Parent = layer })
				local petal = new("ImageLabel", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					Size = UDim2.fromOffset(size, size * 6 / 7),
					Image = Assets.petal,
					ImageTransparency = 1,
					ResampleMode = Enum.ResamplerMode.Pixelated,
					Rotation = rng:NextNumber(0, 360),
					Parent = holder,
				})
				tween(holder, life, { Position = UDim2.new(startX, drift, 0, startY + fall) }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
				local sway = TweenService:Create(
					petal,
					TweenInfo.new(rng:NextNumber(1.4, 2.4), Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
					{ Position = UDim2.fromOffset(rng:NextNumber(14, 30), 0), Rotation = petal.Rotation + rng:NextNumber(-120, 120) }
				)
				sway:Play()
				tween(petal, 1.2, { ImageTransparency = rng:NextNumber(0.25, 0.5) }, Enum.EasingStyle.Quad)
				task.wait(life - 1.6)
				tween(petal, 1.5, { ImageTransparency = 1 }, Enum.EasingStyle.Quad)
				task.wait(1.6)
				sway:Cancel()
				holder:Destroy()
				task.wait(rng:NextNumber(1, 6))
			end
		end)
	end
end

local function spawnTwinkles(window, image, points, pixel)
	LPH_ATTRIBUTES(VM(NONE));
	if not points or #points == 0 then
		return
	end
	for i = 1, 5 do
		task.spawn(function()
			LPH_ATTRIBUTES(VM(NONE));
			local rng = Random.new(os.clock() * 1000 + i * 131)
			task.wait(rng:NextNumber(0, 3))
			while window._alive do
				if not (window.Visible and window.DecorationsEnabled) then
					task.wait(1)
					continue
				end
				local point = points[rng:NextInteger(1, #points)]
				local star = new("Frame", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.fromOffset(point[1] * pixel + pixel / 2, point[2] * pixel + pixel / 2),
					Size = UDim2.fromOffset(pixel, pixel),
					BackgroundColor3 = rgb(255, 236, 246),
					BackgroundTransparency = 1,
					Parent = image,
				})
				local arms = {}
				for _, offset in ipairs({ { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }) do
					table.insert(arms, new("Frame", {
						Position = UDim2.fromOffset(offset[1] * pixel, offset[2] * pixel),
						Size = UDim2.fromOffset(pixel, pixel),
						BackgroundColor3 = rgb(255, 190, 222),
						BackgroundTransparency = 1,
						Parent = star,
					}))
				end
				tween(star, 0.5, { BackgroundTransparency = 0 }, Enum.EasingStyle.Sine)
				for _, arm in ipairs(arms) do
					tween(arm, 0.5, { BackgroundTransparency = 0.25 }, Enum.EasingStyle.Sine)
				end
				task.wait(rng:NextNumber(0.6, 1.1))
				tween(star, 0.6, { BackgroundTransparency = 1 }, Enum.EasingStyle.Sine)
				for _, arm in ipairs(arms) do
					tween(arm, 0.6, { BackgroundTransparency = 1 }, Enum.EasingStyle.Sine)
				end
				task.wait(0.65)
				star:Destroy()
				task.wait(rng:NextNumber(0.4, 2.2))
			end
		end)
	end
end

local function mount(gui)
	LPH_ATTRIBUTES(VM(NONE));
	local ok = false
	if type(gethui) == "function" then
		ok = pcall(function()
			LPH_ATTRIBUTES(VM(NONE));
			gui.Parent = gethui()
		end)
	end
	if not ok then
		ok = pcall(function()
			LPH_ATTRIBUTES(VM(NONE));
			gui.Parent = service("CoreGui")
		end)
	end
	if not ok then
		gui.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")
	end
end

local function draggable(handle, target, onEnd)
	LPH_ATTRIBUTES(VM(NONE));
	local dragging, start, origin
	handle.InputBegan:Connect(function(input)
		LPH_ATTRIBUTES(VM(NONE));
		if isPress(input) then
			dragging, start, origin = true, input.Position, target.Position
		end
	end)
	connect(UserInputService.InputChanged, function(input)
		LPH_ATTRIBUTES(VM(NONE));
		if dragging and isMove(input) then
			local delta = input.Position - start
			target.Position = UDim2.new(origin.X.Scale, origin.X.Offset + delta.X, origin.Y.Scale, origin.Y.Offset + delta.Y)
		end
	end)
	connect(UserInputService.InputEnded, function(input)
		LPH_ATTRIBUTES(VM(NONE));
		if dragging and isPress(input) then
			dragging = false
			if onEnd then
				onEnd()
			end
		end
	end)
end

